import type { BankQuestion } from "@/lib/bank";

/** Indian Economy Basics (Economy): 250 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"eco-basics-1","question":"GDP stands for:","options":["Gross Domestic Product","General Development Programme","Gross Development Product","Grand Domestic Production"],"answer":0,"explanation":"GDP is the total value of final goods and services produced within a country in a year.","difficulty":"easy"},
  {"id":"eco-basics-2","question":"GST was implemented in India from:","options":["1 April 2016","1 July 2017","1 January 2018","1 April 2017"],"answer":1,"explanation":"GST came into force on 1 July 2017.","difficulty":"easy"},
  {"id":"eco-basics-3","question":"The rate at which the RBI lends money to commercial banks is called the:","options":["Reverse repo rate","Repo rate","Bank rate","CRR"],"answer":1,"explanation":"The repo rate is the rate at which the RBI lends to banks against government securities.","difficulty":"moderate"},
  {"id":"eco-basics-4","question":"NITI Aayog replaced which body?","options":["Finance Commission","Planning Commission","National Development Council","Election Commission"],"answer":1,"explanation":"NITI Aayog replaced the Planning Commission on 1 January 2015.","difficulty":"moderate"},
  {"id":"eco-basics-5","question":"The RBI was nationalised in:","options":["1935","1947","1949","1969"],"answer":2,"explanation":"The RBI was nationalised on 1 January 1949.","difficulty":"moderate"},
  {"id":"eco-basics-6","question":"GST was introduced through which Constitutional Amendment?","options":["100th","101st","102nd","103rd"],"answer":1,"explanation":"The 101st Constitutional Amendment Act, 2016 enabled GST.","difficulty":"hard"},
  {"id":"eco-basics-7","question":"The rate at which the RBI borrows money from commercial banks is called the:","options":["Repo rate","Reverse repo rate","Bank rate","MSF rate"],"answer":1,"explanation":"Under the reverse repo, banks park surplus funds with the RBI and earn interest.","difficulty":"hard"},
  {"id":"eco-basics-8","question":"Which of the following is an indirect tax?","options":["Income tax","Corporate tax","GST","Wealth tax"],"answer":2,"explanation":"GST is levied on goods and services and passed on to the consumer, so it is indirect.","difficulty":"hard"},
  {"id":"eco-basics-9","question":"The Fiscal Responsibility and Budget Management (FRBM) Act was enacted in:","options":["1991","2003","2005","2016"],"answer":1,"explanation":"The FRBM Act, 2003 set targets for reducing the fiscal deficit.","difficulty":"very-hard"},
  {"id":"eco-basics-10","question":"Who was the first Governor of the Reserve Bank of India?","options":["C. D. Deshmukh","Sir Osborne Smith","James Braid Taylor","Benegal Rama Rau"],"answer":1,"explanation":"Sir Osborne Smith was the first Governor (1935–37); C. D. Deshmukh was the first Indian Governor.","difficulty":"very-hard"},
  {"id":"eco-basics-11","question":"The Minimum Support Price (MSP) for crops is recommended by the:","options":["NITI Aayog","Commission for Agricultural Costs and Prices (CACP)","Food Corporation of India","Ministry of Finance"],"answer":1,"explanation":"The CACP recommends MSPs; the Cabinet Committee on Economic Affairs approves them.","difficulty":"very-hard"},
  {"id":"eco-basics-12","question":"The Reserve Bank of India was established in:","options":["1921","1935","1947","1949"],"answer":1,"explanation":"The RBI started on 1 April 1935 under the RBI Act, 1934, and was nationalised in 1949.","difficulty":"easy","source":"SSC CGL · IBPS PO"},
  {"id":"eco-basics-13","question":"Inflation measured on the basis of the wholesale price of goods uses the index:","options":["CPI","WPI","GDP deflator","PPI"],"answer":1,"explanation":"WPI tracks wholesale prices; CPI tracks retail prices paid by consumers.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"eco-basics-14","question":"The rate at which the RBI lends short-term funds to commercial banks against securities is the:","options":["Reverse repo rate","Repo rate","Bank rate","CRR"],"answer":1,"explanation":"Repo is the RBI’s lending rate; reverse repo is what it pays banks for their deposits.","difficulty":"moderate","source":"IBPS PO · SBI PO"},
  {"id":"eco-basics-15","question":"Which of these is NOT a direct tax?","options":["Income tax","Corporation tax","Goods and Services Tax","Wealth tax"],"answer":2,"explanation":"GST is an indirect tax, passed on to the consumer.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eco-basics-16","question":"The “Hindu rate of growth”, describing India’s slow growth before the 1980s, was coined by:","options":["Amartya Sen","Raj Krishna","C. Rangarajan","Jagdish Bhagwati"],"answer":1,"explanation":"Economist Raj Krishna used the phrase for the roughly 3.5% growth of 1950–80.","difficulty":"hard","source":"UPSC Prelims · SSC CGL"},
  {"id":"eco-basics-17","question":"Fiscal deficit equals:","options":["Revenue receipts − revenue expenditure","Total expenditure − total receipts excluding borrowings","Total receipts − total expenditure","Interest payments − revenue deficit"],"answer":1,"explanation":"Fiscal deficit is the gap that must be met by borrowing.","difficulty":"very-hard","source":"UPSC Prelims · IBPS PO"},
  {"id":"eco-basics-18","question":"Consider: 1. The repo rate is a quantitative tool of credit control. 2. Raising the CRR increases money supply. 3. Open market operations mean buying and selling government securities. Which are correct?","options":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"A higher CRR locks up more bank money with the RBI and reduces money supply.","difficulty":"hard"},
  {"id":"eco-basics-19","question":"GDP at market price minus depreciation equals:","options":["GNP at market price","NDP at market price","NNP at factor cost","GDP at factor cost"],"answer":1,"explanation":"Subtracting depreciation turns “gross” into “net”: NDP at market price.","difficulty":"hard"},
  {"id":"eco-basics-20","question":"If net factor income from abroad is negative, then:","options":["GNP > GDP","GNP < GDP","GNP = GDP","NNP > GNP"],"answer":1,"explanation":"GNP = GDP + net factor income from abroad, so a negative NFIA makes GNP smaller.","difficulty":"very-hard"},
  {"id":"eco-basics-21","question":"Fiscal deficit minus interest payments is called the:","options":["Revenue deficit","Primary deficit","Effective revenue deficit","Budget deficit"],"answer":1,"explanation":"Primary deficit shows borrowing needed for current spending other than interest.","difficulty":"very-hard"},
  {"id":"eco-basics-22","question":"How many of these statements are correct? I. GST came into force on 1 July 2017. II. The GST Council is chaired by the Union Finance Minister. III. Alcohol for human consumption is outside GST. IV. Crude petroleum is currently taxed under GST.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Crude, diesel, petrol, natural gas and ATF are not yet taxed under GST.","difficulty":"very-hard"},
  {"id":"eco-basics-23","question":"How many of these statements are correct? I. Stagflation means high inflation with stagnant growth. II. Deflation is a fall in the general price level. III. Disinflation means the general price level is falling.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and II. Disinflation is a fall in the rate of inflation; prices still rise, just more slowly.","difficulty":"very-hard"},
  {"id":"eco-basics-24","question":"How many of these statements are correct? I. GDP at factor cost = GDP at market prices − net indirect taxes. II. NNP = GNP − depreciation. III. GNP = GDP + net factor income from abroad.","options":["Only one","Only two","All three","None"],"answer":2,"explanation":"All three are standard national-income identities.","difficulty":"very-hard"},
  {"id":"eco-basics-25","question":"Which measure of money supply is called “broad money”?","options":["M1","M2","M3","M4"],"answer":2,"explanation":"M3 (M1 plus time deposits with banks) is broad money; M1 is narrow money.","difficulty":"very-hard"},
  {"id":"eco-basics-26","question":"If the RBI raises the cash reserve ratio, what follows?","options":["The money multiplier falls","The money multiplier rises","Banks have more funds to lend","The repo rate falls automatically"],"answer":0,"explanation":"The money multiplier is roughly 1 ÷ reserve ratio, so a higher CRR shrinks it and leaves banks less to lend.","difficulty":"very-hard"},
  {"id":"eco-basics-27","question":"How many of these statements are correct? I. Revenue deficit = revenue expenditure − revenue receipts. II. Effective revenue deficit = revenue deficit − grants given for the creation of capital assets. III. Disinvestment proceeds are capital receipts. IV. Interest payments are capital expenditure.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Interest payments create no asset, so they are revenue expenditure.","difficulty":"very-hard","source":"UPSC Prelims · IBPS PO"},
  {"id":"eco-basics-28","question":"Banks must hold reserves equal to 20% of deposits. If the central bank adds ₹1,000 crore of fresh reserves to the system, the maximum increase in deposits under the simple multiplier is:","options":["₹5,000 crore","₹2,000 crore","₹1,200 crore","₹20,000 crore"],"answer":0,"explanation":"Deposit multiplier = 1 ÷ reserve ratio = 1 ÷ 0.2 = 5, so ₹1,000 crore can support ₹5,000 crore of deposits.","difficulty":"very-hard","source":"IBPS PO · UPSC Prelims"},
  {"id":"eco-basics-29","question":"The headquarters of NITI Aayog is located in:","options":["Mumbai","New Delhi","Kolkata","Hyderabad"],"answer":1,"explanation":"NITI Aayog, which replaced the Planning Commission on 1 January 2015, is headquartered in New Delhi with the Prime Minister as its chairperson.","difficulty":"easy","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-30","question":"The Union Budget of India is presented in the Lok Sabha by the:","options":["President","Prime Minister","Finance Minister","RBI Governor"],"answer":2,"explanation":"The Annual Financial Statement under Article 112 is laid before Parliament by the Union Finance Minister on behalf of the President.","difficulty":"easy","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-31","question":"Per capita income of a country is obtained by dividing its national income by its:","options":["Area","Labour force","Population","Number of households"],"answer":2,"explanation":"Per capita income = national income ÷ total population; it is an average and says nothing about how income is distributed.","difficulty":"easy","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-32","question":"Which sector contributes the largest share to India’s GDP?","options":["Agriculture","Manufacturing","Services","Mining"],"answer":2,"explanation":"The services (tertiary) sector contributes well over half of India’s gross value added, while agriculture employs the most people but contributes under a fifth of GDP.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-33","question":"The Consumer Price Index (Combined) used by the RBI for inflation targeting is released by the:","options":["Reserve Bank of India","National Statistical Office","Office of the Economic Adviser, DPIIT","NITI Aayog"],"answer":1,"explanation":"CPI (Combined) is published monthly by the NSO under the Ministry of Statistics; the WPI is released by the Office of the Economic Adviser, DPIIT.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-34","question":"Under the flexible inflation targeting framework, the RBI’s inflation target is:","options":["2% with a band of ±1%","4% with a band of ±2%","6% with a band of ±2%","5% with no band"],"answer":1,"explanation":"The RBI Act (amended 2016) sets a CPI inflation target of 4% with a tolerance band of 2% to 6%, reviewed every five years by the Government.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL"},
  {"id":"eco-basics-35","question":"The Monetary Policy Committee of the RBI consists of how many members?","options":["4","5","6","8"],"answer":2,"explanation":"The MPC has six members: the Governor (chair), the Deputy Governor in charge of monetary policy, one RBI officer and three members nominated by the Central Government.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL"},
  {"id":"eco-basics-36","question":"Under Article 280 of the Constitution, a Finance Commission is constituted by the President every:","options":["3 years","5 years","7 years","10 years"],"answer":1,"explanation":"A Finance Commission is set up every fifth year (or earlier) to recommend how tax proceeds are shared between the Union and the States.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-37","question":"Disguised unemployment in India is most commonly found in:","options":["The IT sector","Agriculture","Banking","Manufacturing"],"answer":1,"explanation":"In disguised unemployment more people are engaged than needed, so removing some would not reduce output; this is typical of family farms in rural India.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-38","question":"If nominal GDP grew by 10% in a year and the GDP deflator rose by 4%, real GDP grew by approximately:","options":["4%","6%","10%","14%"],"answer":1,"explanation":"Real growth ≈ nominal growth − inflation (deflator) = 10% − 4% ≈ 6%. Exactly, 1.10/1.04 − 1 ≈ 5.8%.","difficulty":"hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-39","question":"Which of the following is a capital receipt of the Government of India?","options":["Corporation tax","Dividends from public-sector enterprises","Recovery of loans given to States","Interest received on loans"],"answer":2,"explanation":"Capital receipts either create a liability (borrowings) or reduce an asset (loan recoveries, disinvestment). Taxes, dividends and interest are revenue receipts.","difficulty":"hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-40","question":"“Core inflation” is headline inflation with which items excluded?","options":["Housing and clothing","Food and fuel","Services and imports","Education and health"],"answer":1,"explanation":"Core inflation strips out the volatile food and fuel components to show the underlying trend in prices.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL"},
  {"id":"eco-basics-41","question":"The Marginal Standing Facility (MSF) rate is normally kept at:","options":["25 basis points below the repo rate","Equal to the repo rate","25 basis points above the repo rate","100 basis points above the repo rate"],"answer":2,"explanation":"The MSF rate, at which banks borrow overnight from the RBI in an emergency against SLR securities, forms the ceiling of the LAF corridor, 25 bps above the repo rate; the SDF rate is 25 bps below.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL"},
  {"id":"eco-basics-42","question":"Which RBI facility absorbs surplus liquidity from banks without the RBI giving any collateral?","options":["Repo","Reverse repo","Standing Deposit Facility","Marginal Standing Facility"],"answer":2,"explanation":"The SDF, introduced in April 2022, lets banks park funds with the RBI without the RBI providing securities, unlike the reverse repo; it is the floor of the LAF corridor.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL"},
  {"id":"eco-basics-43","question":"The Phillips curve shows the relationship between:","options":["Inflation and unemployment","Savings and investment","Interest rate and money demand","Tax rate and tax revenue"],"answer":0,"explanation":"The Phillips curve shows an inverse relationship between inflation and unemployment; the tax rate–revenue relation is the Laffer curve.","difficulty":"hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-44","question":"The Lorenz curve is used to measure:","options":["Economic growth","Income inequality","Price elasticity","Balance of payments"],"answer":1,"explanation":"The Lorenz curve plots cumulative income against cumulative population; the farther it lies from the 45° line, the greater the inequality (summarised by the Gini coefficient).","difficulty":"hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-45","question":"Which of the following is recorded in the current account of India’s balance of payments?","options":["Foreign direct investment","Remittances from Indians abroad","External commercial borrowings","Portfolio investment by FIIs"],"answer":1,"explanation":"The current account covers trade in goods and services, income and transfers such as remittances; FDI, FPI and borrowings are capital (financial) account items.","difficulty":"hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-46","question":"By the expenditure method, with private consumption ₹60 lakh crore, investment ₹20 lakh crore, government spending ₹15 lakh crore, exports ₹10 lakh crore and imports ₹15 lakh crore, GDP is:","options":["₹120 lakh crore","₹90 lakh crore","₹100 lakh crore","₹110 lakh crore"],"answer":1,"explanation":"GDP = C + I + G + (X − M) = 60 + 20 + 15 + (10 − 15) = 90 lakh crore; adding imports instead of subtracting gives the wrong 120.","difficulty":"hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-47","question":"How many of these statements are correct? I. The repo rate is the rate at which the RBI lends to banks against government securities. II. The reverse repo rate is higher than the repo rate. III. The bank rate is currently aligned with the MSF rate. IV. CRR is maintained by banks in the form of government securities.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III are correct. II is wrong: the reverse repo rate is below the repo rate. IV is wrong: CRR is cash kept with the RBI; it is the SLR that is held in government securities.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL"},
  {"id":"eco-basics-48","question":"Assertion (A): A rise in the Statutory Liquidity Ratio reduces the lending capacity of banks. Reason (R): SLR requires banks to hold a prescribed share of their net demand and time liabilities in liquid assets such as government securities.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Money locked in SLR assets cannot be lent, so raising the SLR directly shrinks the funds available for credit; R states exactly that mechanism.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL"},
  {"id":"eco-basics-49","question":"Match the budget concept with its definition: 1. Revenue deficit 2. Fiscal deficit 3. Primary deficit 4. Effective revenue deficit; a. Fiscal deficit minus interest payments b. Revenue deficit minus grants for creation of capital assets c. Revenue expenditure minus revenue receipts d. Total expenditure minus total non-borrowing receipts","options":["1-c, 2-d, 3-a, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-a, 3-d, 4-b","1-c, 2-d, 3-b, 4-a"],"answer":0,"explanation":"Revenue deficit = revenue expenditure − revenue receipts; fiscal deficit = total expenditure − (revenue receipts + non-debt capital receipts); primary deficit = fiscal deficit − interest; effective revenue deficit = revenue deficit − grants-in-aid for capital assets.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-50","question":"A government has revenue receipts of ₹20 lakh crore, non-debt capital receipts of ₹2 lakh crore, total expenditure of ₹30 lakh crore and interest payments of ₹8 lakh crore. Its primary deficit is:","options":["₹8 lakh crore","₹10 lakh crore","₹2 lakh crore","Zero"],"answer":3,"explanation":"Fiscal deficit = 30 − (20 + 2) = ₹8 lakh crore; primary deficit = fiscal deficit − interest = 8 − 8 = 0. Forgetting the non-debt capital receipts gives the wrong ₹2 lakh crore.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-51","question":"How many of these statements about GST are correct? I. The GST Council is a constitutional body under Article 279A. II. In the Council, the Centre’s vote has a weight of one-third and the States together two-thirds. III. GST compensation to States was guaranteed for five years from 1 July 2017. IV. Petrol and diesel are taxed under GST at 28%.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct (decisions need a three-fourths weighted majority). IV is wrong: petrol, diesel, ATF, natural gas and crude are outside GST until the Council decides otherwise.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-52","question":"Which of the following is NOT included in the M1 measure of money supply?","options":["Currency with the public","Demand deposits with banks","Time deposits with banks","Other deposits with the RBI"],"answer":2,"explanation":"M1 (narrow money) = currency with the public + demand deposits + other deposits with the RBI. Time deposits enter only M3 (broad money).","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL"},
  {"id":"eco-basics-53","question":"Arrange these events in chronological order: 1. Formation of the State Bank of India 2. Nationalisation of the RBI 3. Launch of the First Five-Year Plan 4. Setting up of the Planning Commission","options":["2, 4, 3, 1","4, 2, 3, 1","2, 3, 4, 1","4, 3, 2, 1"],"answer":0,"explanation":"RBI nationalised on 1 January 1949; Planning Commission set up in March 1950; First Plan began in April 1951; SBI formed on 1 July 1955.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-54","question":"How many of these statements are correct? I. Frictional unemployment occurs when workers are temporarily between jobs. II. Structural unemployment arises from a mismatch between workers’ skills and available jobs. III. Cyclical unemployment rises during a recession. IV. In disguised unemployment the marginal productivity of the extra workers is zero.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are standard definitions: frictional (search time), structural (skill mismatch), cyclical (demand downturn) and disguised (surplus labour with zero marginal product).","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-55","question":"Assertion (A): During a period of high inflation, borrowers gain at the expense of lenders. Reason (R): Inflation reduces the real value of the money that is repaid.","options":["A is true but R is false","Both A and R are true but R does not explain A","Both A and R are true and R explains A","A is false but R is true"],"answer":2,"explanation":"A fixed sum repaid later buys less after inflation, so the lender receives less real value and the borrower effectively repays less; R is precisely the reason.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-56","question":"A country’s GDP at market prices is ₹500 lakh crore, net factor income from abroad is −₹20 lakh crore, depreciation is ₹50 lakh crore and net indirect taxes are ₹30 lakh crore. Its national income (NNP at factor cost) is:","options":["₹400 lakh crore","₹440 lakh crore","₹460 lakh crore","₹480 lakh crore"],"answer":0,"explanation":"GNP = 500 − 20 = 480; NNP at market prices = 480 − 50 = 430; NNP at factor cost = 430 − 30 = 400 lakh crore.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-57","question":"How many of these statements are correct? I. The Fifteenth Finance Commission recommended devolving 41% of the divisible pool of central taxes to the States. II. Corporation tax is a direct tax. III. Customs duty collected by the Union forms part of the divisible pool shared with States. IV. Cesses levied by the Union are part of the divisible pool.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: cesses and surcharges are retained wholly by the Centre and are excluded from the pool shared under Article 270.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-58","question":"Match the publication with the body that releases it: 1. Human Development Report 2. World Economic Outlook 3. Global Competitiveness Report 4. Ease of Doing Business (till 2021); a. World Bank b. IMF c. UNDP d. World Economic Forum","options":["1-c, 2-b, 3-d, 4-a","1-c, 2-a, 3-d, 4-b","1-d, 2-b, 3-c, 4-a","1-b, 2-c, 3-d, 4-a"],"answer":0,"explanation":"HDR and the HDI come from UNDP, the World Economic Outlook from the IMF, the Global Competitiveness Report from the WEF, and the (discontinued) Doing Business rankings were the World Bank’s.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id": "eco-basics-59", "question": "The economic reforms India began in 1991 are often summed up as “LPG”, which stands for:", "options": ["Liberalisation, Privatisation and Globalisation", "Licensing, Production and Growth", "Land, Population and GDP", "Liberalisation, Planning and Growth"], "answer": 0, "explanation": "The 1991 reforms (PM P. V. Narasimha Rao, Finance Minister Manmohan Singh) liberalised industry and trade, opened the public sector to private players and integrated India with the world economy.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "eco-basics-60", "question": "Which body regulates the securities (stock) market in India?", "options": ["RBI", "SEBI", "IRDAI", "PFRDA"], "answer": 1, "explanation": "SEBI, set up in 1988 and given statutory powers in 1992, regulates stock exchanges and securities. IRDAI regulates insurance and PFRDA pensions.", "difficulty": "easy", "source": "SSC GD · RRB Group D"},
  {"id": "eco-basics-61", "question": "India’s First Five-Year Plan (1951–56) gave the highest priority to:", "options": ["Heavy industry", "Defence", "Agriculture, including irrigation", "Exports"], "answer": 2, "explanation": "The First Plan, based on the Harrod–Domar model, focused on agriculture and irrigation after Partition-era food shortages. Heavy industry was the focus of the Second Plan.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "eco-basics-62", "question": "The Second Five-Year Plan, which stressed rapid industrialisation through heavy industries, was based on the model of:", "options": ["Harrod and Domar", "P. C. Mahalanobis", "D. R. Gadgil", "Arthur Lewis"], "answer": 1, "explanation": "The Second Plan (1956–61) followed the Mahalanobis model of building capital-goods industries. The Harrod–Domar model underlay the First Plan.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "eco-basics-63", "question": "A Gini coefficient of 0 indicates:", "options": ["Perfect inequality", "Zero inflation", "Zero GDP growth", "Perfect equality of income"], "answer": 3, "explanation": "The Gini coefficient runs from 0 (everyone has the same income) to 1 (one person has all the income); it is derived from the Lorenz curve.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO"},
  {"id": "eco-basics-64", "question": "Which organisation replaced the General Agreement on Tariffs and Trade (GATT) in 1995?", "options": ["IMF", "World Bank", "World Trade Organization", "UNCTAD"], "answer": 2, "explanation": "The WTO came into being on 1 January 1995 after the Uruguay Round, replacing GATT (1947). The IMF and World Bank date from the 1944 Bretton Woods conference.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "eco-basics-65", "question": "Inflation caused by a rise in the prices of raw materials, wages or fuel is called:", "options": ["Demand-pull inflation", "Cost-push inflation", "Stagflation", "Deflation"], "answer": 1, "explanation": "When production costs rise, firms raise prices: cost-push inflation. Demand-pull inflation comes from too much demand chasing limited goods.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "eco-basics-66", "question": "Gresham’s law in economics states that:", "options": ["Good money drives bad money out of circulation", "Bad money drives good money out of circulation", "Supply creates its own demand", "The quantity of money determines the price level"], "answer": 1, "explanation": "When two forms of money of the same face value circulate, people hoard the more valuable (good) one and spend the debased (bad) one. “Supply creates its own demand” is Say’s law.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-67", "question": "Goods whose demand rises when their price rises, typically cheap staple foods consumed by very poor households, are called:", "options": ["Veblen goods", "Giffen goods", "Normal goods", "Complementary goods"], "answer": 1, "explanation": "Giffen goods are inferior staples: a price rise makes the poor too poor to afford better food, so they buy more of the staple. Veblen goods also defy the law of demand, but they are luxury status goods.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-68", "question": "A devaluation of the rupee generally makes:", "options": ["Indian exports cheaper for foreign buyers and imports costlier in India", "Both exports and imports cheaper", "Indian exports costlier and imports cheaper", "No difference to exports and imports"], "answer": 0, "explanation": "After devaluation a dollar buys more rupees, so Indian goods become cheaper abroad while foreign goods cost more rupees at home.", "difficulty": "hard", "source": "IBPS PO · SBI PO · UPSC Prelims"},
  {"id": "eco-basics-69", "question": "The official poverty estimate of 21.9% for India in 2011–12 was based on the methodology of which committee?", "options": ["Lakdawala Committee", "Rangarajan Committee", "Alagh Committee", "Tendulkar Committee"], "answer": 3, "explanation": "The Planning Commission’s 2011–12 estimate of 21.9% used the Tendulkar methodology. The Rangarajan Committee (2014) proposed a higher line giving 29.5%, but it was not formally adopted.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-70", "question": "The term “twin deficit” refers to an economy running:", "options": ["A revenue deficit and a primary deficit together", "A fiscal deficit and a current account deficit together", "A trade deficit and a services deficit together", "A budget deficit in two consecutive years"], "answer": 1, "explanation": "Twin deficits mean the government spends more than it earns (fiscal deficit) while the country spends more abroad than it earns (current account deficit).", "difficulty": "hard", "source": "IBPS PO · SBI PO · UPSC Prelims"},
  {"id": "eco-basics-71", "question": "In Indian planning, the period of “Plan Holiday”, when annual plans replaced a five-year plan, was:", "options": ["1962–65", "1985–87", "1966–69", "1978–80"], "answer": 2, "explanation": "After the Third Plan (1961–66), war and drought led to three annual plans in 1966–69. 1978–80 was the Janata government’s “rolling plan”, a different arrangement.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-72", "question": "In India, an investment of 10% or more of the post-issue equity of a listed company by a foreign investor is classified as:", "options": ["Foreign portfolio investment", "Foreign direct investment", "External commercial borrowing", "A non-resident deposit"], "answer": 1, "explanation": "Following the Mayaram Committee, the 10% line separates FDI (a lasting interest) from FPI (below 10% in a listed company).", "difficulty": "hard", "source": "IBPS PO · SBI PO · UPSC Prelims"},
  {"id": "eco-basics-73", "question": "How many of these are direct taxes in India? I. Corporation tax II. Customs duty III. Securities transaction tax IV. Capital gains tax", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "Corporation tax, securities transaction tax and capital gains tax are direct taxes administered by the CBDT. Customs duty is an indirect tax under the CBIC. STT is the usual trap.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-74", "question": "Assertion (A): Indirect taxes are generally regressive. Reason (R): An indirect tax on a good is the same for every buyer, so it takes a larger share of a poor person’s income than of a rich person’s.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Everyone pays the same tax on, say, a packet of salt, which is a bigger fraction of a low income. R correctly explains why A is true.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-75", "question": "Match the term with its meaning: 1. Demand-pull inflation 2. Cost-push inflation 3. Stagflation 4. Disinflation; a. A fall in the rate of inflation b. Excess aggregate demand pushing up prices c. Rising input costs pushing up prices d. High inflation along with stagnant output", "options": ["1-b, 2-c, 3-d, 4-a", "1-c, 2-b, 3-d, 4-a", "1-b, 2-c, 3-a, 4-d", "1-b, 2-d, 3-c, 4-a"], "answer": 0, "explanation": "Disinflation means prices still rise but more slowly; it differs from deflation, where the price level itself falls.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO"},
  {"id": "eco-basics-76", "question": "Nominal GDP rises from ₹200 lakh crore to ₹264 lakh crore in a year while the GDP deflator rises from 100 to 120. The growth of real GDP is:", "options": ["32%", "12%", "10%", "20%"], "answer": 2, "explanation": "Real GDP in the second year = 264 ÷ 1.20 = ₹220 lakh crore. Growth = (220 − 200) ÷ 200 = 10%. 32% is the nominal growth and 12% is the trap of simple subtraction (32 − 20).", "difficulty": "very-hard", "source": "SSC CGL · UPSC Prelims"},
  {"id": "eco-basics-77", "question": "How many of these statements about MGNREGA are correct? I. It was enacted in 2005. II. It guarantees 100 days of wage employment in a financial year to every rural household whose adults volunteer for unskilled manual work. III. At least one-third of the beneficiaries are to be women. IV. Unemployment allowance is paid by the Central Government.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: the unemployment allowance is the liability of the State Government, while the Centre bears the full cost of unskilled wages.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-78", "question": "Which of the following is NOT recorded in the current account of India’s balance of payments?", "options": ["Export of software services", "Remittances from Indians working abroad", "Foreign direct investment inflows", "Interest paid on external loans"], "answer": 2, "explanation": "The current account covers goods, services, primary income (such as interest) and transfers (such as remittances). FDI is an investment flow recorded in the capital/financial account.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · UPSC Prelims"},
  {"id": "eco-basics-79", "question": "Arrange in chronological order: 1. Establishment of the WTO 2. Bretton Woods conference 3. Launch of GST in India 4. India’s new economic policy (LPG reforms)", "options": ["2, 4, 1, 3", "4, 2, 1, 3", "2, 1, 4, 3", "2, 4, 3, 1"], "answer": 0, "explanation": "Bretton Woods 1944 → LPG reforms 1991 → WTO 1995 → GST 2017.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "eco-basics-80", "question": "Assertion (A): A cut in the cash reserve ratio increases the lending capacity of banks. Reason (R): The RBI pays banks a high rate of interest on their CRR balances.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "A is true: a lower CRR frees deposits for lending. R is false: the RBI pays no interest on CRR balances, which is why banks prefer a lower CRR.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · UPSC Prelims"},
  {"id": "eco-basics-81", "question": "How many of these statements are correct? I. Firms under perfect competition are price takers. II. A monopolist is always a price taker. III. Under oligopoly, each firm takes its decisions independently of its rivals. IV. Products under monopolistic competition are differentiated.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only I and IV are correct. A monopolist is a price maker, and oligopolists are interdependent: each watches and reacts to its few rivals.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "eco-basics-82", "question": "If the marginal propensity to consume is 0.8, an increase in investment of ₹100 crore will raise national income by:", "options": ["₹80 crore", "₹125 crore", "₹500 crore", "₹400 crore"], "answer": 2, "explanation": "Investment multiplier = 1 ÷ (1 − MPC) = 1 ÷ 0.2 = 5. Increase in income = 5 × 100 = ₹500 crore.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO"},
  {"id": "eco-basics-83", "question": "How many of the following are used in calculating UNDP’s Human Development Index? I. Life expectancy at birth II. Mean years of schooling III. Expected years of schooling IV. Gross national income per capita (PPP) V. Poverty headcount ratio", "options": ["Only two", "Only three", "Only four", "All five"], "answer": 2, "explanation": "HDI combines health (life expectancy), education (mean and expected years of schooling) and standard of living (GNI per capita at PPP). Poverty is measured separately by the Multidimensional Poverty Index.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-84", "question": "Agriculture, fishing, forestry and mining belong to which sector of the economy?", "options": ["Secondary sector", "Tertiary sector", "Quaternary sector", "Primary sector"], "answer": 3, "explanation": "The primary sector draws goods directly from nature. Manufacturing and construction form the secondary sector, and services such as banking and transport the tertiary sector.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "eco-basics-85", "question": "According to the law of demand, other things remaining the same, when the price of a good falls its quantity demanded:", "options": ["Falls", "Stays the same", "First falls and then rises", "Rises"], "answer": 3, "explanation": "Price and quantity demanded move in opposite directions, so the demand curve slopes downward. Giffen goods are the rare exception.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "eco-basics-86", "question": "The Economic Survey of India, presented just before the Union Budget, is prepared under the guidance of the:", "options": ["Comptroller and Auditor General", "Governor of the RBI", "Chairman of NITI Aayog", "Chief Economic Adviser"], "answer": 3, "explanation": "The Economic Division of the Department of Economic Affairs (Ministry of Finance) prepares the Survey under the Chief Economic Adviser, and the Finance Minister tables it in Parliament.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "eco-basics-87", "question": "Engel’s law states that as a household’s income rises:", "options": ["The share of income spent on food falls", "The demand for luxuries falls", "The share of income saved falls", "The amount spent on food falls"], "answer": 0, "explanation": "The amount spent on food may still rise, but it rises more slowly than income, so the share of income going to food falls. This is why a falling food share is used as a sign of rising living standards.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-88", "question": "A vertical demand curve shows that the price elasticity of demand is:", "options": ["Equal to one", "Zero", "Infinite", "Greater than one"], "answer": 1, "explanation": "A vertical curve means the same quantity is bought at every price, so demand is perfectly inelastic (elasticity zero). A horizontal demand curve is the one with infinite elasticity.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "eco-basics-89", "question": "The opportunity cost of a choice is:", "options": ["The value of the next best alternative given up", "The sum of all alternatives given up", "The cost of producing one more unit", "The money paid for the chosen item"], "answer": 0, "explanation": "Opportunity cost is the value of the best option forgone, not of all options. The cost of one more unit is marginal cost.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "eco-basics-90", "question": "A good whose demand falls when consumers’ income rises is called a:", "options": ["Normal good", "Complementary good", "Luxury good", "Inferior good"], "answer": 3, "explanation": "With higher income people switch from inferior goods (for example coarse grains) to better substitutes. For normal and luxury goods demand rises with income. A Giffen good is a special kind of inferior good.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "eco-basics-91", "question": "In India, fiscal policy (decisions on taxation and government spending) is decided by the:", "options": ["NITI Aayog", "Securities and Exchange Board of India", "Reserve Bank of India", "Government of India through the Ministry of Finance"], "answer": 3, "explanation": "Fiscal policy is set by the government and voted through the Budget. Monetary policy (interest rates and money supply) is the RBI’s job, and NITI Aayog is a policy think tank.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "eco-basics-92", "question": "The term ‘demographic dividend’ refers to:", "options": ["Profits from population-control programmes", "Extra tax revenue from a growing population", "Money sent home by emigrants", "The growth potential when the working-age share of the population is large"], "answer": 3, "explanation": "When the share of people aged about 15–64 is high and dependants are few, more workers and savings can speed growth, if there are jobs and skills for them. India is in this phase now.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-93", "question": "The price of a good rises from ₹10 to ₹12 and its quantity demanded falls from 100 units to 90 units. The price elasticity of demand (in absolute value) is:", "options": ["0.2", "0.5", "1.0", "2.0"], "answer": 1, "explanation": "Change in quantity = −10/100 = −10%; change in price = 2/10 = 20%. Elasticity = 10% ÷ 20% = 0.5, so demand is inelastic. Inverting the ratio gives the trap answer 2.0.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · RBI Grade B"},
  {"id": "eco-basics-94", "question": "Under the GST rate rationalisation that took effect on 22 September 2025, the main GST slabs became:", "options": ["5%, 12%, 18% and 28%", "5% and 18%, with a special 40% rate for sin and luxury goods", "12% and 28% only", "A single rate of 18%"], "answer": 1, "explanation": "The GST Council in September 2025 cut the four main slabs (5, 12, 18, 28%) to two, 5% and 18%, and set a special 40% rate for items such as tobacco products and luxury goods.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · RBI Grade B"},
  {"id": "eco-basics-95", "question": "‘Crowding out’ in economics means that:", "options": ["Heavy government borrowing raises interest rates and reduces private investment", "Large firms drive small firms out of business", "Imports push domestic producers out of the market", "Rural workers migrate to overcrowded cities"], "answer": 0, "explanation": "When the government borrows heavily from the market it competes with private borrowers for loanable funds, pushing up interest rates so that some private investment is dropped.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-96", "question": "A ‘liquidity trap’ is a situation in which:", "options": ["Inflation is so high that people refuse to hold money", "The government cannot sell its bonds", "Banks hold too little cash to meet withdrawals", "Interest rates are so low that further increases in money supply fail to lower them or raise spending"], "answer": 3, "explanation": "Keynes described how, near a zero interest rate, people prefer to hold any extra money, so monetary policy loses its power and fiscal policy is needed. A bank running short of cash is a liquidity crisis, a different idea.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-97", "question": "The ‘paradox of thrift’ suggests that if all households try to save more at the same time:", "options": ["Interest rates will rise", "Total savings will rise sharply", "Investment will rise automatically", "Aggregate demand and income may fall, so total savings may not rise"], "answer": 3, "explanation": "Higher saving means lower consumption, which cuts demand, output and income; with lower income, total saving may stay the same or even fall. What is prudent for one family can hurt the economy as a whole.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-98", "question": "A fixed deposit pays 7% interest a year while consumer price inflation is 9%. The approximate real rate of return is:", "options": ["16%", "7%", "2%", "−2%"], "answer": 3, "explanation": "Real return ≈ nominal rate − inflation = 7% − 9% = −2%. The depositor’s money buys less at the end of the year than at the start, even though it has earned interest.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · RBI Grade B"},
  {"id": "eco-basics-99", "question": "According to the Periodic Labour Force Survey (PLFS) 2023–24, which sector employs the largest share of India’s workforce?", "options": ["Construction", "Manufacturing", "Services", "Agriculture and allied activities"], "answer": 3, "explanation": "Agriculture employs about 46% of workers even though it contributes less than a fifth of GVA, while services contribute the largest share of output. This gap is the root of disguised unemployment in farming.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-100", "question": "In the Union Budget 2025–26, the Government of India set its fiscal deficit target at:", "options": ["4.4% of GDP", "6.4% of GDP", "3.0% of GDP", "5.9% of GDP"], "answer": 0, "explanation": "The Budget for 2025–26 aimed at a fiscal deficit of 4.4% of GDP, down from 4.8% (revised estimate) in 2024–25. 5.9% and 6.4% were the targets of 2023–24 and 2022–23.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · RBI Grade B"},
  {"id": "eco-basics-101", "question": "‘Hot money’ refers to:", "options": ["Cash kept by the RBI for emergencies", "Short-term capital that moves quickly between countries to chase higher returns", "Money earned from illegal activities", "Counterfeit currency"], "answer": 1, "explanation": "Hot money is mainly short-term portfolio flows that rush in when interest rates or returns are attractive and leave just as fast, which can destabilise exchange rates. Black money is the term for illegal income.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · RBI Grade B"},
  {"id": "eco-basics-102", "question": "How many of these statements about price elasticity of demand are correct? I. Demand for necessities tends to be inelastic. II. A good with many close substitutes has elastic demand. III. If demand is elastic, a cut in price raises total expenditure on the good. IV. Elasticity is the same at every point on a straight-line, downward-sloping demand curve.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: on a straight-line demand curve elasticity falls from very high near the price axis to zero at the quantity axis, being 1 at the midpoint, even though the slope is constant.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO · RBI Grade B"},
  {"id": "eco-basics-103", "question": "Assertion (A): Under a progressive income tax, the average tax rate rises as income rises. Reason (R): Under a progressive tax, the marginal tax rate is lower than the average tax rate.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "A is true but R is false. In a progressive system the marginal rate (on the last rupee) is higher than the average rate, and it is exactly this that pulls the average rate up as income grows.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-104", "question": "Match the economist with the idea: 1. Adam Smith 2. J. M. Keynes 3. Thomas Malthus 4. David Ricardo; a. Comparative advantage b. Population tends to outgrow the food supply c. Effective demand determines output and employment d. The ‘invisible hand’ of the market", "options": ["1-c, 2-d, 3-b, 4-a", "1-d, 2-c, 3-b, 4-a", "1-a, 2-c, 3-b, 4-d", "1-d, 2-c, 3-a, 4-b"], "answer": 1, "explanation": "Smith (Wealth of Nations, 1776) wrote of the invisible hand, Keynes (General Theory, 1936) of effective demand, Malthus of population outrunning food, and Ricardo of comparative advantage in trade.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-105", "question": "In a two-sector economy, consumption is C = 100 + 0.75Y and investment is fixed at ₹150 crore (all figures in ₹ crore). The equilibrium level of national income is:", "options": ["₹1,000 crore", "₹250 crore", "₹400 crore", "₹600 crore"], "answer": 0, "explanation": "At equilibrium Y = C + I = 100 + 0.75Y + 150, so 0.25Y = 250 and Y = ₹1,000 crore. Equivalently, autonomous spending of 250 × multiplier 1/(1 − 0.75) = 4 gives 1,000.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO · RBI Grade B"},
  {"id": "eco-basics-106", "question": "Arrange these in chronological order: 1. Nationalisation of 14 major commercial banks 2. Industrial Policy Resolution adopted 3. FEMA enacted to replace FERA 4. High-yielding varieties programme that began the Green Revolution", "options": ["4, 2, 1, 3", "2, 1, 4, 3", "2, 4, 3, 1", "2, 4, 1, 3"], "answer": 3, "explanation": "The Industrial Policy Resolution came in 1956, the high-yielding varieties programme in 1966, bank nationalisation in July 1969, and the Foreign Exchange Management Act in 1999.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-107", "question": "How many of these statements about price indices in India are correct? I. The Wholesale Price Index does not cover services. II. The Consumer Price Index covers both goods and services. III. The GDP deflator covers all goods and services produced in the country. IV. The Wholesale Price Index is compiled and released by the RBI.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: the WPI is released by the Office of the Economic Adviser in the Department for Promotion of Industry and Internal Trade, while CPI is released by the National Statistics Office.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-108", "question": "Which of the following would NOT be counted in India’s GDP for the year?", "options": ["Value of new houses built during the year", "Salary paid to a government-school teacher", "Value of wheat a farmer grows and keeps for his own family", "Price received for selling a five-year-old car"], "answer": 3, "explanation": "GDP counts only goods and services produced in the year, so the resale of a used car is excluded (only a dealer’s commission would count). Production for own use, like the farmer’s wheat, is imputed and included.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-109", "question": "Assertion (A): After a devaluation, a country’s trade balance often worsens at first before it improves. Reason (R): Import bills rise at once because of the higher prices, while export and import volumes take time to adjust.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "This is the J-curve effect: in the short run contracts are fixed and demand is inelastic, so the higher rupee cost of imports widens the deficit; later, cheaper exports and costlier imports change volumes and the balance improves. R explains A.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO · RBI Grade B"},
  {"id": "eco-basics-110", "question": "Match the committee with its subject: 1. Rangarajan Committee (2014) 2. Raja Chelliah Committee (1991) 3. Malhotra Committee (1993) 4. Abid Hussain Committee (1997); a. Small-scale industries b. Insurance sector reforms c. Tax reforms d. Measurement of poverty", "options": ["1-d, 2-c, 3-b, 4-a", "1-d, 2-b, 3-c, 4-a", "1-d, 2-c, 3-a, 4-b", "1-c, 2-d, 3-b, 4-a"], "answer": 0, "explanation": "Rangarajan reviewed poverty estimation, Raja Chelliah recommended tax reforms in 1991, R. N. Malhotra opened up insurance (leading to IRDA), and Abid Hussain studied small-scale industries.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-111", "question": "In a year, nominal GDP grows by 12%, the GDP deflator rises by 5% and population grows by 2%. The approximate growth in real per capita income is:", "options": ["3%", "7%", "5%", "10%"], "answer": 2, "explanation": "Real GDP growth ≈ 12% − 5% = 7%; real per capita growth ≈ 7% − 2% = 5%. Stopping at 7% forgets population, and 10% wrongly ignores inflation.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO · RBI Grade B"},
  {"id": "eco-basics-112", "question": "How many of these statements about the Union Budget are correct? I. Article 112 of the Constitution requires an Annual Financial Statement to be laid before Parliament. II. A Money Bill can be introduced only in the Lok Sabha. III. The Consolidated Fund of India is provided for in Article 266. IV. The Contingency Fund of India is placed at the disposal of the Finance Minister.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: under Article 267 the Contingency Fund is at the disposal of the President, who can advance money from it for unforeseen spending pending Parliament’s approval.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-113", "question": "Assertion (A): A large fiscal deficit financed by borrowing directly from the central bank tends to be inflationary. Reason (R): Such monetisation of the deficit increases the base money in the economy.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "When the central bank buys government debt with newly created money, reserve (base) money rises and, through the money multiplier, broad money rises too; more money chasing the same goods pushes up prices. So R explains A.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-114", "question": "The basic economic problem of choice arises because:", "options": ["Money is printed by the central bank", "Resources are limited while human wants are unlimited", "Prices keep rising", "Governments collect taxes"], "answer": 1, "explanation": "Scarcity of land, labour and capital relative to wants forces every society to decide what to produce, how and for whom.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "eco-basics-115", "question": "A market with only one seller of a product that has no close substitutes is called:", "options": ["Monopoly", "Oligopoly", "Perfect competition", "Monopsony"], "answer": 0, "explanation": "A monopolist controls the whole supply and can set the price. Monopsony is the opposite case: a single buyer.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "eco-basics-116", "question": "A market dominated by a few large sellers, each of whose pricing decisions affects the others, is called:", "options": ["Monopolistic competition", "Perfect competition", "Oligopoly", "Monopoly"], "answer": 2, "explanation": "In an oligopoly, such as telecom or aviation, a handful of firms watch and react to one another's moves. Monopolistic competition has many sellers of differentiated goods.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO"},
  {"id": "eco-basics-117", "question": "If the price of petrol rises sharply, the demand for petrol cars is likely to:", "options": ["Rise, because cars and petrol are substitutes", "Stay unchanged", "Rise, because cars become cheaper", "Fall, because cars and petrol are complements"], "answer": 3, "explanation": "Complements are used together, so a costlier complement makes the other good less attractive. With substitutes such as tea and coffee, a price rise of one raises demand for the other.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO"},
  {"id": "eco-basics-118", "question": "To avoid double counting while measuring GDP, statisticians count:", "options": ["Only the value of final goods and services, or the value added at each stage", "The value of all goods sold, including raw materials", "Only exports", "Only goods produced by the government"], "answer": 0, "explanation": "Counting both wheat and the bread made from it would count the wheat twice. Using final goods or summing value added at each stage gives the same, correct total.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO"},
  {"id": "eco-basics-119", "question": "A thirsty person gets less and less extra satisfaction from each additional glass of water. This illustrates the:", "options": ["Law of demand", "Law of diminishing marginal utility", "Law of supply", "Law of increasing returns"], "answer": 1, "explanation": "Marginal utility, the satisfaction from one more unit, falls as consumption rises. This is one reason why demand curves slope downward.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO"},
  {"id": "eco-basics-120", "question": "Old-age pensions and scholarships paid by the government are NOT included in national income because they:", "options": ["Are too small to matter", "Are paid in cash", "Are transfer payments made without any current production in return", "Are counted in exports"], "answer": 2, "explanation": "Transfer payments merely move income from taxpayers to recipients; no good or service is produced for them, so including them would overstate output.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · UPSC Prelims"},
  {"id": "eco-basics-121", "question": "A farmer sells wheat worth ₹100 to a miller (with no inputs bought), the miller sells flour worth ₹150 to a baker, and the baker sells bread worth ₹220 to consumers. How much do these transactions add to GDP?", "options": ["₹470", "₹370", "₹120", "₹220"], "answer": 3, "explanation": "Value added is ₹100 + ₹50 + ₹70 = ₹220, which equals the value of the final good, bread. Adding all sales (₹470) double-counts the wheat and flour.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "eco-basics-122", "question": "If the government fixes a maximum price (price ceiling) below the market equilibrium price, the most likely result is:", "options": ["A shortage, often accompanied by rationing or black markets", "A surplus of the good", "No change in the market", "A rise in the quantity supplied"], "answer": 0, "explanation": "At the lower price buyers want more and sellers offer less, so demand exceeds supply. A price floor above equilibrium, by contrast, creates a surplus.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · UPSC Prelims"},
  {"id": "eco-basics-123", "question": "Luxury goods whose demand rises as their price rises, because a high price signals status, are called:", "options": ["Giffen goods", "Veblen goods", "Inferior goods", "Normal necessities"], "answer": 1, "explanation": "Veblen goods, such as designer watches, are prized for conspicuous consumption. Giffen goods are cheap staples of the very poor whose demand rises with price for a different reason.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "eco-basics-124", "question": "The cross-price elasticity of demand between two goods is negative. The two goods are most likely:", "options": ["Substitutes", "Unrelated", "Complements", "Both inferior goods"], "answer": 2, "explanation": "Negative cross elasticity means a rise in the price of one lowers demand for the other, as with printers and ink cartridges. Substitutes have positive cross elasticity.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "eco-basics-125", "question": "A factory dumps waste into a river, hurting fishermen downstream who receive no compensation. Economists call this a:", "options": ["Positive externality", "Public good", "Merit good", "Negative externality"], "answer": 3, "explanation": "A negative externality is a cost imposed on third parties outside the market. A corrective (Pigouvian) tax or regulation makes the polluter bear that cost.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · UPSC Prelims"},
  {"id": "eco-basics-126", "question": "Goods like primary education and vaccination, which society considers so valuable that they would be under-consumed if left to the market, are called:", "options": ["Merit goods", "Demerit goods", "Giffen goods", "Inferior goods"], "answer": 0, "explanation": "Merit goods create benefits beyond the individual buyer, so governments subsidise or provide them. Demerit goods, such as tobacco, are over-consumed and often taxed.", "difficulty": "hard", "source": "UPSC Prelims · IBPS PO"},
  {"id": "eco-basics-127", "question": "How many of these statements about price controls are correct? I. A price ceiling below the equilibrium price creates a shortage. II. A minimum support price above the market price can lead to large government stocks. III. Rationing often accompanies a binding price ceiling. IV. A price floor fixed below the equilibrium price changes the market outcome.", "options": ["Only three", "Only one", "Only two", "All four"], "answer": 0, "explanation": "I, II and III are correct. A floor below equilibrium is non-binding: the market price already exceeds it, so nothing changes, and IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "eco-basics-128", "question": "Match the market form with its feature. A. Perfect competition  B. Monopoly  C. Monopolistic competition  D. Oligopoly; 1. Many sellers of differentiated products such as toothpaste brands  2. A few interdependent sellers  3. A single seller with no close substitutes  4. Many sellers of an identical product, each a price taker", "options": ["A-4, B-3, C-2, D-1", "A-4, B-3, C-1, D-2", "A-3, B-4, C-1, D-2", "A-4, B-1, C-3, D-2"], "answer": 1, "explanation": "Perfect competitors cannot influence price; a monopolist faces no rival; monopolistic competitors compete through branding and product differences; oligopolists react to each other's moves.", "difficulty": "very-hard", "source": "UPSC Prelims · IBPS PO"},
  {"id": "eco-basics-129", "question": "How many of these statements about public goods are correct? I. One person's use does not reduce what is available to others (non-rival). II. It is hard to stop non-payers from using them (non-excludable). III. The free-rider problem means markets tend to under-supply them. IV. A public good must be produced by a government-owned enterprise.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct; national defence and street lighting are classic examples. Governments usually fund or arrange public goods, but private firms can produce them under contract, so IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "eco-basics-130", "question": "Assertion (A): A rising GDP does not necessarily mean rising economic welfare. Reason (R): GDP leaves out unpaid household work and does not subtract environmental damage, and it says nothing about how income is distributed.", "options": ["A is true but R is false", "Both A and R are true but R is not the correct explanation of A", "A is false but R is true", "Both A and R are true and R is the correct explanation of A"], "answer": 3, "explanation": "These gaps are exactly why GDP can grow while welfare stagnates, and why measures such as the HDI and green accounting were developed.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "eco-basics-131", "question": "How many of these are correctly treated in India's GDP? I. The sale of a used car is excluded, except for the dealer's commission. II. Buying shares on the stock exchange is excluded. III. An imputed rent for owner-occupied houses is included. IV. Interest the government pays on its past borrowing is included as factor income.", "options": ["Only one", "Only three", "Only two", "All four"], "answer": 1, "explanation": "I, II and III are correct. Interest on public debt, much of it raised for consumption or war, is treated as a transfer payment rather than income from current production, so IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims · IBPS PO"},
  {"id": "eco-basics-132", "question": "Match the cost concept with an example or definition. A. Fixed cost  B. Variable cost  C. Marginal cost  D. Average cost; 1. Extra cost of producing one more unit  2. Total cost divided by the number of units  3. Rent of a factory that stays the same whatever the output  4. Raw materials, which rise as output rises", "options": ["A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2", "A-3, B-1, C-4, D-2", "A-3, B-4, C-1, D-2"], "answer": 3, "explanation": "Fixed costs must be paid even at zero output; variable costs change with output; marginal cost is the addition from one more unit; average cost spreads the total over all units.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO"},
  {"id": "eco-basics-133", "question": "For an economy where depreciation is positive, net indirect taxes are positive, and net factor income from abroad is positive but smaller than net indirect taxes, arrange these in decreasing order: 1. GNP at market prices  2. NNP at factor cost  3. GDP at market prices  4. NDP at market prices", "options": ["1-3-4-2", "3-1-4-2", "1-3-2-4", "1-4-3-2"], "answer": 0, "explanation": "GNP(MP) = GDP(MP) + NFIA, so 1 > 3; NDP(MP) = GDP(MP) − depreciation, so 3 > 4; NNP(FC) = NDP(MP) + NFIA − net indirect taxes, which is below NDP(MP) because NFIA is smaller than net indirect taxes.", "difficulty": "very-hard", "source": "UPSC Prelims · IBPS PO"},
  {"id":"eco-basics-134","question":"An economy's output at basic prices is ₹1,000 crore and intermediate consumption is ₹600 crore. Product taxes are ₹50 crore and product subsidies ₹10 crore. Its GDP is:","options":["₹400 crore","₹440 crore","₹460 crore","₹450 crore"],"answer":1,"explanation":"GVA at basic prices = 1,000 − 600 = ₹400 crore; GDP = GVA at basic prices + product taxes − product subsidies = 400 + 50 − 10 = ₹440 crore. Adding the subsidies instead of subtracting gives ₹460 crore.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-basics-135","question":"How many of these statements about India's national accounts (2011–12 series) are correct? I. GVA at basic prices = GVA at factor cost + production taxes − production subsidies. II. GDP = GVA at basic prices + product taxes − product subsidies. III. Land revenue and stamp duties are treated as production taxes, levied whatever the volume of output. IV. GST is treated as a production tax.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. GST is levied per unit of product sold, so it is a product tax that is added to GVA at basic prices to reach GDP; IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-basics-136","question":"In a year, compensation of employees is ₹300 crore, operating surplus ₹150 crore, mixed income of the self-employed ₹100 crore and net factor income from abroad −₹10 crore. National income (NNP at factor cost) is:","options":["₹550 crore","₹560 crore","₹540 crore","₹640 crore"],"answer":2,"explanation":"Adding the factor incomes earned at home gives NDP at factor cost = 300 + 150 + 100 = ₹550 crore. Adding net factor income from abroad gives NNP at factor cost = 550 − 10 = ₹540 crore.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-basics-137","question":"In an open economy the marginal propensity to consume out of disposable income is 0.8, the proportional tax rate is 25% and the marginal propensity to import is 0.1. The investment multiplier is:","options":["2.5","3.33","5.0","2.0"],"answer":3,"explanation":"k = 1/[1 − b(1 − t) + m] = 1/[1 − 0.8 × 0.75 + 0.1] = 1/0.5 = 2. Ignoring imports gives 2.5, ignoring taxes gives 3.33, and the closed-economy, no-tax multiplier is 5.","difficulty":"very-hard","source":"RBI Grade B Phase 2"},
  {"id":"eco-basics-138","question":"In a simple Keynesian model with an MPC of 0.75 and lump-sum taxes, the government raises both its spending and its taxes by ₹100 crore. Equilibrium income rises by:","options":["₹100 crore","Zero","₹400 crore","₹300 crore"],"answer":0,"explanation":"The spending multiplier is 1/0.25 = 4 (+₹400 crore) and the tax multiplier is −0.75/0.25 = −3 (−₹300 crore), so income rises by ₹100 crore: the balanced budget multiplier is 1.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-basics-139","question":"With an MPC of 0.75, the government cuts lump-sum taxes by ₹40 crore while keeping spending unchanged. Equilibrium income rises by:","options":["₹160 crore","₹120 crore","₹40 crore","₹30 crore"],"answer":1,"explanation":"The tax multiplier is −b/(1 − b) = −3, so a ₹40 crore tax cut raises income by ₹120 crore. It is smaller than the spending multiplier (4) because part of the tax cut is saved, not spent.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-basics-140","question":"The consumption function is C = 60 + 0.75Y (₹ crore). At what level of income is saving exactly zero?","options":["₹80 crore","₹60 crore","₹240 crore","₹45 crore"],"answer":2,"explanation":"Saving S = Y − C = −60 + 0.25Y, which is zero when Y = 60/0.25 = ₹240 crore. At this break-even point the APC is exactly 1; dividing 60 by 0.75 gives the wrong ₹80 crore.","difficulty":"moderate","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-basics-141","question":"An industry needs ₹3 of capital for every ₹1 of annual output. If its output rises from ₹500 crore to ₹550 crore, the induced net investment according to the accelerator principle is:","options":["₹1,650 crore","₹16.7 crore","₹50 crore","₹150 crore"],"answer":3,"explanation":"Net investment = capital-output ratio × change in output = 3 × 50 = ₹150 crore. Multiplying the whole output (550) by 3 gives the total capital stock, not new investment.","difficulty":"moderate","source":"RBI Grade B Phase 2"},
  {"id":"eco-basics-142","question":"The price of a good rises from ₹10 to ₹12 and the quantity demanded falls from 100 to 80 units. Using the midpoint (arc) method, the price elasticity of demand (absolute value) is about:","options":["1.22","1.00","0.82","2.00"],"answer":0,"explanation":"Midpoint method: (20/90)/(2/11) ≈ 0.222/0.182 ≈ 1.22. Using the initial values instead gives (20/100)/(2/10) = 1.0, which is why the arc method is preferred for large changes.","difficulty":"very-hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-basics-143","question":"The price elasticity of demand for a firm's product is 0.5 (absolute). If the firm raises its price by 10%, its total revenue will:","options":["Fall by about 5%","Rise by about 4.5%","Rise by about 10%","Fall by about 4.5%"],"answer":1,"explanation":"Quantity falls by 0.5 × 10% = 5%, so revenue becomes 1.10 × 0.95 = 1.045 times: a rise of about 4.5%. With inelastic demand, price and total revenue move in the same direction.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-basics-144","question":"When household incomes rise by 20%, the quantity demanded of good X falls by 5%. The income elasticity of demand and the type of good are:","options":["+0.25; a necessity","−4.0; a Giffen good","−0.25; an inferior good","+4.0; a luxury good"],"answer":2,"explanation":"Income elasticity = −5/20 = −0.25. A negative income elasticity marks an inferior good; it would be a Giffen good only if demand also rose with its own price, which the data do not show.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eco-basics-145","question":"A consumer is willing to pay at most ₹50 for the first unit of a good, ₹40 for the second, ₹30 for the third and ₹20 for the fourth. The market price is ₹30 and she buys three units. Her consumer surplus is:","options":["₹120","₹90","₹20","₹30"],"answer":3,"explanation":"Consumer surplus = (50 − 30) + (40 − 30) + (30 − 30) = ₹30. ₹120 is her total willingness to pay and ₹90 her spending; buying the fourth unit would have cut the surplus to ₹20.","difficulty":"very-hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-basics-146","question":"If the supply of a good is perfectly inelastic, a per-unit tax on it is borne:","options":["Entirely by sellers","Entirely by buyers","Equally by buyers and sellers","By whichever side pays it to the government"],"answer":0,"explanation":"Sellers cannot cut quantity, so the price buyers pay does not change and sellers absorb the whole tax. In general, the less elastic side bears more of the tax, whoever legally pays it.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-basics-147","question":"A firm in a perfectly competitive market finds that, at its best output, price is ₹40, average variable cost is ₹45 and average total cost is ₹55. In the short run it should:","options":["Keep producing, since the price covers part of the fixed cost","Shut down, since the price does not cover average variable cost","Keep producing, as long as the price is above marginal cost","Raise its price to ₹55 so that it covers all of its costs"],"answer":1,"explanation":"If price is below AVC, every unit produced adds to losses; shutting down limits the loss to the fixed cost. A competitive firm is a price taker, so it cannot raise its price.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-basics-148","question":"At its profit-maximising output a firm charges ₹50 while its marginal cost is ₹30. Its Lerner index of market power and the implied price elasticity of demand are:","options":["0.6 and 1.67","0.4 and 0.4","0.67 and 1.5","0.4 and 2.5"],"answer":3,"explanation":"Lerner index = (P − MC)/P = 20/50 = 0.4, and at profit maximum it equals 1/|e|, so |e| = 2.5. Dividing by MC instead of price gives 0.67.","difficulty":"very-hard","source":"RBI Grade B Phase 2"},
  {"id":"eco-basics-149","question":"The kinked demand curve model of oligopoly (Sweezy) is mainly used to explain:","options":["Why prices stay rigid even when costs change within a range","Why price wars break out as soon as one firm cuts its price","Why firms form cartels to fix output quotas and share profits","Why a dominant firm sets the price and smaller rivals follow it"],"answer":0,"explanation":"Rivals follow a price cut but not a rise, so demand is elastic above the current price and inelastic below it; the resulting gap in MR lets costs shift without changing the profit-maximising price.","difficulty":"hard","source":"RBI Grade B Phase 2"},
  {"id":"eco-basics-150","question":"Two firms each choose a 'high' or 'low' price. Whatever its rival does, each firm earns more by choosing the low price, yet both would earn more if both chose high. Without an enforceable agreement, the likely outcome is that:","options":["Both choose the high price, since it maximises their joint profit","Both choose the low price, an equilibrium that leaves both worse off","One firm chooses high and the other low, taking turns each period","No stable outcome exists, since each keeps changing its choice"],"answer":1,"explanation":"Low price is each firm's dominant strategy, so (low, low) is the Nash equilibrium even though (high, high) is better for both: the prisoner's dilemma, which is why cartels are unstable.","difficulty":"very-hard","source":"RBI Grade B Phase 2 · CAT"},
  {"id":"eco-basics-151","question":"In long-run equilibrium under monopolistic competition, a typical firm:","options":["Earns supernormal profit protected by brand loyalty","Produces at minimum average cost like a competitive firm","Earns normal profit but produces with excess capacity","Faces a perfectly elastic demand curve at the market price"],"answer":2,"explanation":"Free entry removes supernormal profit, so price equals AC; but the firm's demand curve slopes down, so it touches AC to the left of its minimum, leaving unused capacity.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-basics-152","question":"Under the law of variable proportions, a rational producer chooses to operate in the stage where:","options":["The average product of the variable input is still rising","The marginal product of the variable input has turned negative","Total product falls as more of the variable input is added","Both AP and MP are falling but MP is still positive"],"answer":3,"explanation":"In Stage I the fixed factor is under-used, so adding the variable input raises its average product; in Stage III MP is negative. The rational stage is Stage II, where AP and MP fall but MP is positive.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-basics-153","question":"A firm's production function is Q = 5L^0.6 K^0.5. If it doubles both labour and capital, its output:","options":["Rises about 2.14 times: increasing returns to scale","Exactly doubles: constant returns to scale","Rises about 1.52 times: decreasing returns to scale","Rises about 1.1 times: decreasing returns to scale"],"answer":0,"explanation":"Output rises by 2^(0.6+0.5) = 2^1.1 ≈ 2.14 times. Since the exponents sum to more than 1, there are increasing returns to scale; 1.52 is 2^0.6, the effect of doubling labour alone.","difficulty":"very-hard","source":"RBI Grade B Phase 2"},
  {"id":"eco-basics-154","question":"A production possibility curve is concave (bowed out) to the origin mainly because:","options":["The economy's resources and technology stay fixed along the curve","The opportunity cost of a good rises as more of it is produced","All resources are fully and efficiently employed along the curve","The economy can produce only two goods with its available resources"],"answer":1,"explanation":"Resources are not equally suited to both goods, so shifting more of them to one good means giving up ever larger amounts of the other. The other options are assumptions behind any PPC, not the reason for its shape.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-basics-155","question":"Two indifference curves of the same consumer cannot intersect because that would violate:","options":["The diminishing marginal rate of substitution","The completeness of the consumer's preferences","Transitivity of preferences, given that more is preferred","The convexity of the consumer's budget set"],"answer":2,"explanation":"If two curves crossed, the common point would be equally good as two bundles of which one has more of both goods; by transitivity they would be equal, contradicting the assumption that more is preferred.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-basics-156","question":"A consumer has ₹600 to spend; good X costs ₹20 and good Y costs ₹30 (X on the horizontal axis). If the price of X doubles while income and the price of Y stay the same, the budget line:","options":["Shifts inward in parallel, with both intercepts halved","Pivots inward around the X-intercept, its slope becoming −1/3","Pivots outward around the Y-intercept, its slope becoming −1/3","Pivots inward around the Y-intercept, its slope becoming −4/3"],"answer":3,"explanation":"The Y-intercept stays at 600/30 = 20, while the X-intercept falls from 30 to 15. The slope −Px/Py changes from −2/3 to −40/30 = −4/3.","difficulty":"very-hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-basics-157","question":"An allocation of resources is said to be Pareto efficient when:","options":["No one can be made better off without making someone else worse off","Income and wealth are shared equally among all the members of society","Total output is the largest possible, whatever its distribution among people","Every single person is at least as well off as in the previous allocation"],"answer":0,"explanation":"Pareto efficiency only rules out waste: no reallocation can help someone without hurting another. A highly unequal allocation can still be Pareto efficient, so it says nothing about fairness.","difficulty":"moderate","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-basics-158","question":"A monopolist sells at a price of ₹100, where the price elasticity of demand is 2 (absolute). Its marginal revenue at this point is:","options":["₹200","₹100","₹150","₹50"],"answer":3,"explanation":"MR = P(1 − 1/|e|) = 100 × (1 − 0.5) = ₹50. MR equals price only under perfect competition; a monopolist never produces where demand is inelastic, since MR would be negative there.","difficulty":"hard","source":"RBI Grade B Phase 2"},
  {"id":"eco-basics-159","question":"Government debt is 60% of GDP, the primary deficit is 2% of GDP, the nominal interest rate on debt is 7% and nominal GDP grows at 10%. Using Δd = pd + d(r − g)/(1 + g), the debt ratio over the year changes by about:","options":["+0.36 percentage points","+3.80 percentage points","−1.64 percentage points","+2.00 percentage points"],"answer":0,"explanation":"Δd = 2 + 60 × (0.07 − 0.10)/1.10 ≈ 2 − 1.64 = +0.36 points. Because growth exceeds the interest rate, the debt ratio rises far less than the primary deficit alone suggests.","difficulty":"very-hard","source":"RBI Grade B Phase 2 · UPSC Prelims"},
  {"id":"eco-basics-160","question":"In a year, tax revenue grows by 15% while nominal GDP grows by 10%; part of the extra revenue came from new tax rates announced in the budget. Which statement is correct?","options":["Tax elasticity is 1.5, and buoyancy would exclude the effect of the new rates","Tax buoyancy is 1.5, while elasticity would exclude the effect of the new rates","Both tax buoyancy and tax elasticity are 0.67 in this case","Tax buoyancy is 0.67, since revenue grew more slowly than GDP"],"answer":1,"explanation":"Buoyancy = 15/10 = 1.5 and includes revenue from discretionary changes in rates and base. Elasticity measures the automatic response of revenue to income with the tax structure unchanged.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-basics-161","question":"The Laffer curve suggests that:","options":["Higher tax rates always raise total revenue for the government","Tax revenue depends only on the tax base, not on the tax rates","Beyond some point, higher tax rates can reduce total revenue","Indirect taxes collect more revenue than direct taxes at any rate"],"answer":2,"explanation":"At zero and at 100% tax rates revenue is zero, so revenue peaks at some rate in between; above it, higher rates shrink or drive away the tax base enough to lower revenue.","difficulty":"moderate","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-basics-162","question":"A manufacturer sells goods worth ₹1,000 plus 18% GST to a retailer. The retailer adds value of ₹500 and sells them for ₹1,500 plus 18% GST to a consumer. The retailer's net GST payment in cash, and the total GST collected by the government, are:","options":["₹270 and ₹450","₹90 and ₹180","₹270 and ₹270","₹90 and ₹270"],"answer":3,"explanation":"The retailer owes 18% of ₹1,500 = ₹270 but claims credit for the ₹180 paid on purchases, paying ₹90. Total tax = 180 + 90 = ₹270, i.e. 18% of the final price: input tax credit removes the cascading effect.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-basics-163","question":"Match: 1. Consolidated Fund of India 2. Contingency Fund of India 3. Public Account of India 4. Annual Financial Statement; a. Article 112 b. Article 266(1) c. Article 266(2) d. Article 267","options":["1-c, 2-d, 3-b, 4-a","1-b, 2-d, 3-c, 4-a","1-b, 2-a, 3-c, 4-d","1-d, 2-b, 3-c, 4-a"],"answer":1,"explanation":"Article 266(1) creates the Consolidated Fund, 266(2) the Public Account, Article 267 the Contingency Fund, and Article 112 requires the Annual Financial Statement (the budget).","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"eco-basics-164","question":"Which of these is NOT charged on the Consolidated Fund of India, and so must be voted by the Lok Sabha?","options":["Salary and allowances of the President","Salaries and allowances of Supreme Court judges","Interest and other charges on the debt of the Union","Salaries and allowances of Union ministers"],"answer":3,"explanation":"Article 112(3) lists charged items such as the President's emoluments, Supreme Court judges' salaries, the CAG's salary and debt charges; these are discussed but not voted. Ministers' salaries are voted expenditure.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"eco-basics-165","question":"Match the cut motion with its form: 1. Policy cut 2. Economy cut 3. Token cut; a. Reduce the demand by ₹100 to voice a specific grievance b. Reduce the demand to ₹1, signalling disapproval of the policy behind it c. Reduce the demand by a stated amount that represents a possible saving","options":["1-a, 2-c, 3-b","1-b, 2-a, 3-c","1-b, 2-c, 3-a","1-c, 2-b, 3-a"],"answer":2,"explanation":"A policy cut reduces the demand to ₹1, an economy cut reduces it by a specified amount, and a token cut reduces it by ₹100 to air a particular grievance.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"eco-basics-166","question":"A 'vote on account' allows the government to:","options":["Draw money from the Consolidated Fund for part of the year until the budget is passed","Spend from the Contingency Fund without any later approval from Parliament","Pass all remaining demands for grants together without discussing them","Change tax rates during the year without bringing a fresh Finance Bill"],"answer":0,"explanation":"Under Article 116, the Lok Sabha can grant an advance for part of the year so that spending can continue before the full budget is passed. Putting all remaining demands to vote together is the guillotine.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"eco-basics-167","question":"How many of these statements about Union Budget reforms are correct? I. The Railway Budget was merged with the Union Budget from 2017–18. II. The date of presenting the Union Budget was advanced to 1 February from 2017. III. The distinction between plan and non-plan expenditure was removed from 2017–18. IV. An Outcome Budget was first presented in 2005–06.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The 2017 reforms merged the rail budget, advanced the budget to 1 February and replaced plan/non-plan with revenue/capital classification; outcome budgeting began in 2005–06.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"eco-basics-168","question":"In the Fifteenth Finance Commission's formula for sharing the divisible pool among States, which criterion carried the highest weight?","options":["Population (2011 Census)","Income distance","Area","Demographic performance"],"answer":1,"explanation":"Income distance carried 45%, favouring poorer States; population and area had 15% each, forest and ecology 10%, demographic performance 12.5% and tax effort 2.5%.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"eco-basics-169","question":"Assertion (A): States get no share of the cesses and surcharges levied by the Union Government. Reason (R): Cesses and surcharges are excluded from the divisible pool of central taxes under Article 270.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Only taxes in the divisible pool are shared according to the Finance Commission's award; cesses and surcharges lie outside it, so their growing share reduces what States receive.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-basics-170","question":"Match the Article with its subject: 1. Article 270 2. Article 275 3. Article 282 4. Article 293; a. Borrowing by States b. Grants for any public purpose, even outside the Union's legislative field c. Statutory grants-in-aid to States in need of help d. Taxes levied by the Union and shared with States","options":["1-d, 2-b, 3-c, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-d, 2-c, 3-b, 4-a"],"answer":3,"explanation":"Article 270 covers sharing of Union taxes, 275 statutory grants on Finance Commission advice, 282 discretionary grants for any public purpose, and 293 borrowing by States.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"eco-basics-171","question":"A government's revenue deficit is 3.5% of GDP, and grants it gives for the creation of capital assets are 1.2% of GDP. Its effective revenue deficit is:","options":["4.7% of GDP","1.2% of GDP","2.3% of GDP","3.5% of GDP"],"answer":2,"explanation":"Effective revenue deficit = revenue deficit − grants for creation of capital assets = 3.5 − 1.2 = 2.3% of GDP. Such grants are revenue spending on paper but create assets, so they are taken out.","difficulty":"moderate","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-basics-172","question":"A tax takes ₹10,000 from an income of ₹1 lakh and ₹30,000 from an income of ₹2 lakh. This tax is:","options":["Progressive, as the average tax rate rises with income","Proportional, as the tax paid rises along with income","Regressive, as the marginal tax rate falls with income","Proportional, as the marginal tax rate stays constant"],"answer":0,"explanation":"The average rate rises from 10% to 15%, so the tax is progressive; the marginal rate on the extra ₹1 lakh is 20%. A tax that merely rises in rupees with income can still be proportional or regressive.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-basics-173","question":"Under a hypothetical slab system, income up to ₹3 lakh is tax-free, income from ₹3 lakh to ₹6 lakh is taxed at 5% and income from ₹6 lakh to ₹9 lakh at 10%. For an income of ₹8 lakh, the tax, average rate and marginal rate are:","options":["₹80,000; average 10%; marginal 10%","₹35,000; average 4.4%; marginal 10%","₹50,000; average 6.3%; marginal 10%","₹35,000; average 10%; marginal 4.4%"],"answer":1,"explanation":"Tax = 5% of ₹3 lakh + 10% of ₹2 lakh = 15,000 + 20,000 = ₹35,000, an average rate of 35,000/8,00,000 ≈ 4.4%. The marginal rate is the rate on the last rupee, 10%; charging 10% on all of it is the common slab error.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-basics-174","question":"Zero-based budgeting requires that:","options":["Every department's budget is kept at zero growth in nominal terms","The budget is balanced, with total spending equal to total receipts","Every item of spending is justified afresh, not as a rise on last year","Spending on any scheme with zero outcomes in the past is stopped"],"answer":2,"explanation":"Incremental budgeting takes last year's allocation as given and argues only about the increase; zero-based budgeting starts from zero and makes each activity justify its whole cost.","difficulty":"moderate","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-basics-175","question":"According to the Ricardian equivalence proposition, a tax cut financed by government borrowing, with spending unchanged:","options":["Raises consumption by the full amount of the tax cut","Leaves consumption unchanged, as households save for future taxes","Raises interest rates and crowds out private investment","Raises consumption by the tax cut times the multiplier"],"answer":1,"explanation":"Forward-looking households see that today's borrowing means higher taxes later, so they save the whole tax cut; private saving rises exactly as public saving falls, and demand is unchanged.","difficulty":"very-hard","source":"RBI Grade B Phase 2"},
  {"id":"eco-basics-176","question":"Assertion (A): A government can run a fiscal deficit in the same year that it runs a primary surplus. Reason (R): The fiscal deficit equals the primary deficit plus interest payments.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"If interest payments exceed the primary surplus, the fiscal deficit is positive: for example, a primary surplus of 1% of GDP with interest of 3% of GDP gives a fiscal deficit of 2%.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-basics-177","question":"The Coase theorem states that, if property rights are clearly defined and bargaining costs are negligible:","options":["The government must impose a tax equal to the external cost","The polluter must always be made to pay for the damage caused","Private bargaining gives an efficient outcome, whoever holds the rights","An externality can be removed only by setting up a public enterprise"],"answer":2,"explanation":"With costless bargaining, the parties will trade until the efficient level of the activity is reached; the assignment of rights affects who pays whom, not the efficient outcome. A tax equal to marginal external cost is the Pigouvian solution.","difficulty":"very-hard","source":"RBI Grade B Phase 2"},
  {"id":"eco-basics-178","question":"Fish in the open sea, which anyone may catch and whose stock is depleted by each catch, are an example of goods that are:","options":["Non-rival and non-excludable, i.e. public goods","Excludable but non-rival, i.e. club goods","Rival but non-excludable, i.e. common resources","Rival and excludable, i.e. private goods"],"answer":2,"explanation":"One person's catch leaves less for others (rival), but no one can easily be kept out (non-excludable). Such common resources tend to be over-used: the tragedy of the commons.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-basics-179","question":"After buying a comprehensive car insurance policy, a driver starts parking carelessly in unsafe places. Economists call this:","options":["Adverse selection","Free riding","Signalling","Moral hazard"],"answer":3,"explanation":"Moral hazard is a change in behaviour after a contract, because the insured no longer bears the full cost of risk. Adverse selection arises before the contract, when riskier people are more likely to buy insurance.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-basics-180","question":"In the Union Budget, which of these is NOT shown as a source of financing the fiscal deficit?","options":["Market borrowings through dated securities","Disinvestment proceeds from public sector firms","Securities issued against small savings","Net external assistance from abroad"],"answer":1,"explanation":"Disinvestment is a non-debt capital receipt counted above the line, so it reduces the fiscal deficit; the deficit itself is financed by borrowing from the market, small savings, external sources and similar items.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-basics-181","question":"The FRBM Review Committee (2017), chaired by N. K. Singh, recommended which variable as the primary anchor of fiscal policy?","options":["The general government debt-to-GDP ratio","The fiscal deficit as a share of GDP","The revenue deficit as a share of GDP","The primary deficit as a share of GDP"],"answer":0,"explanation":"The committee proposed a general government debt ceiling of 60% of GDP (40% Centre, 20% States) as the anchor, with the fiscal deficit as the operational target to reach it.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-basics-182","question":"An economy produces only apples and oranges. Year 1: 10 kg of apples at ₹5 and 20 kg of oranges at ₹2. Year 2: 12 kg of apples at ₹6 and 25 kg of oranges at ₹3. With Year 1 as the base, real GDP growth in Year 2 is about:","options":["63.3%","10.0%","22.2%","33.6%"],"answer":2,"explanation":"Real GDP in Year 2 at Year 1 prices = 12×5 + 25×2 = ₹110, against ₹90 in Year 1, a growth of 22.2%. Nominal GDP grew 147/90 − 1 = 63.3%, and the deflator rose about 33.6%.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-basics-183","question":"An economy invests 30% of its GDP and its incremental capital-output ratio (ICOR) is 4. By the Harrod–Domar relation, its growth rate is, and to grow at 9% with the same ICOR it would need an investment rate of:","options":["7.5%; 36%","7.5%; 40.5%","12.0%; 36%","7.5%; 33%"],"answer":0,"explanation":"g = s/ICOR = 30/4 = 7.5%. To grow at 9%, investment must be 9 × 4 = 36% of GDP. Multiplying by 4.5 or adding the growth gap to 30% are the usual slips.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-basics-184","question":"A country's GDP grows at 5.5% a year and its population at 2% a year. Using the rule of 70, its per capita income will double in about:","options":["13 years","20 years","35 years","10 years"],"answer":1,"explanation":"Per capita income grows at about 5.5 − 2 = 3.5% a year, so it doubles in roughly 70/3.5 = 20 years. Using total GDP growth gives 13 years, which ignores population growth.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-basics-185","question":"A population has 300 people aged 0–14, 600 aged 15–64 and 100 aged 65 and above. Its total dependency ratio is:","options":["40.0%","50.0%","16.7%","66.7%"],"answer":3,"explanation":"Dependency ratio = (0–14 + 65+)/(15–64) = 400/600 ≈ 66.7%. 50% is only the young-age ratio and 16.7% the old-age ratio; 40% wrongly divides by the whole population.","difficulty":"moderate","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-basics-186","question":"Of 1,000 persons aged 15 and above, 470 are working and 30 are not working but are seeking or available for work. The labour force participation rate, worker population ratio and unemployment rate are:","options":["50%, 47% and 6%","50%, 47% and 3%","47%, 50% and 6%","50%, 44% and 6.4%"],"answer":0,"explanation":"Labour force = 470 + 30 = 500, so LFPR = 50% and WPR = 470/1,000 = 47%. The unemployment rate is measured against the labour force: 30/500 = 6%, not 30/1,000 = 3%.","difficulty":"very-hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-basics-187","question":"Among the activity status approaches used in India's Periodic Labour Force Survey, which usually gives the HIGHEST unemployment rate?","options":["Usual status (principal plus subsidiary)","Current weekly status","Current daily status","Usual principal status alone"],"answer":2,"explanation":"Current daily status counts person-days of unemployment over the reference week, capturing intermittent joblessness; usual status counts anyone with work for a sizeable part of the year as employed, so its rate is the lowest.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"eco-basics-188","question":"On a Lorenz diagram, the area between the line of equality and the Lorenz curve is 0.15, while the total area under the line of equality is 0.5. The Gini coefficient is:","options":["0.15","0.30","0.35","0.70"],"answer":1,"explanation":"Gini = area between the line and the curve ÷ total area under the line = 0.15/0.5 = 0.30. 0.35 is the area under the Lorenz curve, not an inequality measure.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-basics-189","question":"A country's HDI dimension indices are: health 0.8, education 0.6 and income 0.5. Using the UNDP's current method, its HDI is about:","options":["0.633","0.621","0.240","0.650"],"answer":1,"explanation":"Since 2010 the HDI is the geometric mean of the three indices: (0.8 × 0.6 × 0.5)^(1/3) = 0.24^(1/3) ≈ 0.621. The arithmetic mean, 0.633, was the older method; 0.24 is the product before taking the cube root.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-basics-190","question":"How many of these statements about the global Multidimensional Poverty Index (UNDP–OPHI) are correct? I. It uses the Alkire–Foster method. II. Its dimensions are health, education and standard of living. III. A person deprived in at least one-third of the weighted indicators is counted as multidimensionally poor. IV. It is based only on household income below a poverty line.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. The MPI measures overlapping deprivations such as nutrition, schooling, sanitation and cooking fuel; it does not use income at all, so IV is wrong.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"eco-basics-191","question":"Arrange these Indian poverty estimation panels in chronological order: 1. Tendulkar Expert Group 2. Alagh Task Force 3. Rangarajan Expert Group 4. Lakdawala Expert Group","options":["2, 4, 3, 1","4, 2, 1, 3","2, 1, 4, 3","2, 4, 1, 3"],"answer":3,"explanation":"Alagh Task Force (1979) set calorie-based poverty lines, Lakdawala (1993) moved to state-specific lines, Tendulkar (2009) shifted away from calories, and Rangarajan (2014) revised the Tendulkar lines.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"eco-basics-192","question":"In W. Arthur Lewis's dual-sector model of development, growth proceeds as:","options":["Surplus farm labour moves to industry at a near-constant wage until the surplus runs out","Industry grows first through exports, and agriculture modernises only much later","Capital flows from rich to poor countries until returns are equal everywhere","Population growth slows as income rises, which frees up savings for investment"],"answer":0,"explanation":"With surplus labour in subsistence farming, industry can hire at a wage just above subsistence; profits are reinvested and expansion continues until the surplus is absorbed (the Lewis turning point).","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-basics-193","question":"In W. W. Rostow's stages of economic growth, which stage comes immediately after the 'take-off'?","options":["Preconditions for take-off","Drive to maturity","Age of high mass consumption","Traditional society"],"answer":1,"explanation":"Rostow's sequence is traditional society, preconditions for take-off, take-off, drive to maturity and the age of high mass consumption.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-basics-194","question":"The Kuznets curve hypothesis holds that, as per capita income grows, income inequality:","options":["Rises steadily without limit","Falls steadily from the start","Stays the same at all incomes","First rises and then falls"],"answer":3,"explanation":"Kuznets argued that early industrialisation widens gaps between the modern and traditional sectors, but as more people move into the modern sector inequality declines, giving an inverted-U.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-basics-195","question":"In one hour of labour, a worker in India can make 4 shirts or 2 kg of rice; a worker in Bangladesh can make 3 shirts or 1 kg of rice. According to comparative advantage:","options":["India should export both goods, as it is better at both","Bangladesh should export rice and India should export shirts","India should export rice and Bangladesh should export shirts","There are no gains from trade, as India is better at both"],"answer":2,"explanation":"A shirt costs India 0.5 kg of rice but Bangladesh only 0.33 kg, so Bangladesh has the comparative advantage in shirts and India in rice, even though India has an absolute advantage in both.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-basics-196","question":"A country's export price index is 120, its import price index is 150 and its export volume index is 125 (all with the same base = 100). Its net barter terms of trade and income terms of trade are:","options":["80 and 100","125 and 100","80 and 150","125 and 156"],"answer":0,"explanation":"Net barter terms = Px/Pm × 100 = 120/150 × 100 = 80. Income terms = (Px/Pm) × export volume = 0.8 × 125 = 100: worse prices, but enough extra exports to keep import capacity unchanged.","difficulty":"very-hard","source":"RBI Grade B Phase 2"},
  {"id":"eco-basics-197","question":"Which of these is INCLUDED in India's GDP?","options":["Lottery winnings of a household","Purchase of a second-hand flat","Old-age pension paid by the government","Imputed rent of owner-occupied houses"],"answer":3,"explanation":"Owner-occupiers are treated as renting the house to themselves, so an imputed rent is counted as a service produced. Lottery wins and pensions are transfers, and a second-hand flat was produced in an earlier year.","difficulty":"moderate","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-basics-198","question":"By Okun's law with a coefficient of 2, if the actual unemployment rate is 7% and the natural rate is 5%, actual output is about:","options":["4% below potential","2% below potential","1% below potential","7% below potential"],"answer":0,"explanation":"Output gap ≈ −2 × (7 − 5) = −4%, so output is about 4% below potential. Dividing the 2-point unemployment gap by the coefficient gives the wrong 1%.","difficulty":"hard","source":"RBI Grade B Phase 2"},
  {"id":"eco-basics-199","question":"How many commercial banks were nationalised in India in the two rounds of bank nationalisation?","options":["6 in 1969 and 14 in 1980","14 in 1969 and 7 in 1980","20 in 1969, with none in 1980","14 in 1969 and 6 in 1980"],"answer":3,"explanation":"Fourteen major banks with deposits above ₹50 crore were nationalised in July 1969, and six more in April 1980, bringing 20 banks into the public sector.","difficulty":"hard","source":"UPSC Prelims · IBPS PO Mains"},
  {"id":"eco-basics-200","question":"The idea of a 'rolling plan', adopted by the Janata Government for 1978–80, is associated with:","options":["Gunnar Myrdal","P. C. Mahalanobis","W. Arthur Lewis","D. R. Gadgil"],"answer":0,"explanation":"Gunnar Myrdal proposed rolling plans, in which targets and allocations are revised every year and a new year is added; Mahalanobis designed the Second Plan and Gadgil the formula for central assistance to States.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"eco-basics-201","question":"Goods produced this year but still unsold with the producer at the end of the year are:","options":["Excluded from GDP until the year in which they are sold","Included in this year's GDP as a change in inventories","Included in GDP only if they happen to be capital goods","Excluded from GDP but added to the nation's stock of wealth"],"answer":1,"explanation":"GDP measures production, not sales, so unsold output counts as investment in inventories this year. When it is sold next year, inventories fall by the same amount, avoiding double counting.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-basics-202","question":"How many of these statements are correct? I. Dadabhai Naoroji made one of the earliest estimates of India's per capita income, for 1867–68. II. V. K. R. V. Rao estimated national income for 1931–32 using a mix of the income and output methods. III. The National Income Committee of 1949 was chaired by P. C. Mahalanobis. IV. The Central Statistical Organisation prepared India's first official national income estimates in 1935.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. The CSO was set up only in 1951, after independence; official national income estimates began after the National Income Committee's work, so IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"eco-basics-203","question":"Match the pre-independence or early plan with its author: 1. Bombay Plan 2. Gandhian Plan 3. People's Plan 4. Sarvodaya Plan; a. Jayaprakash Narayan b. M. N. Roy c. Shriman Narayan Agarwal d. A group of leading industrialists","options":["1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-b, 4-a"],"answer":3,"explanation":"The Bombay Plan (1944) came from industrialists such as J. R. D. Tata and G. D. Birla; the Gandhian Plan from S. N. Agarwal; the People's Plan from M. N. Roy; and the Sarvodaya Plan (1950) from Jayaprakash Narayan.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"eco-basics-204","question":"Demand for a good is Qd = 100 − 2P and supply is Qs = 20 + 2P. If the government fixes a minimum price of ₹25, the resulting surplus is:","options":["20 units","10 units","50 units","70 units"],"answer":0,"explanation":"Equilibrium is P = 20, Q = 60. At ₹25, Qd = 50 and Qs = 70, so 20 units remain unsold. 50 and 70 are the separate quantities, not the surplus.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-basics-205","question":"Demand is Qd = 100 − 2P and supply is Qs = 20 + 2P. The government levies a tax of ₹4 per unit, collected from sellers. In the new equilibrium:","options":["Buyers pay ₹24; sellers get ₹20","Buyers pay ₹22; sellers get ₹18","Buyers pay ₹20; sellers get ₹16","Buyers pay ₹21; sellers get ₹17"],"answer":1,"explanation":"Supply becomes Qs = 20 + 2(P − 4); setting 100 − 2P = 12 + 2P gives P = ₹22, so sellers keep ₹18. With equally sloped curves the ₹4 burden is split equally, whoever pays it legally.","difficulty":"very-hard","source":"RBI Grade B Phase 2"},
  {"id":"eco-basics-206","question":"In a market where demand is Qd = 100 − 2P and supply Qs = 20 + 2P, a ₹4 per-unit tax cuts the quantity traded from 60 to 56. The deadweight loss of the tax is:","options":["₹16","₹224","₹8","₹4"],"answer":2,"explanation":"Deadweight loss = ½ × tax × fall in quantity = ½ × 4 × 4 = ₹8. ₹224 (4 × 56) is the revenue collected, which is a transfer rather than a loss.","difficulty":"very-hard","source":"RBI Grade B Phase 2"},
  {"id":"eco-basics-207","question":"For the demand curve Q = 100 − 2P, the price elasticity of demand (absolute) at a price of ₹20 is:","options":["1.50","0.40","2.00","0.67"],"answer":3,"explanation":"Point elasticity = (dQ/dP) × P/Q = 2 × 20/60 ≈ 0.67. Elasticity changes along a straight-line demand curve; it equals 1 only at the midpoint (P = 25).","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-basics-208","question":"A firm's total cost is TC = 100 + 10Q + Q². At what output is its average total cost lowest, and what is that minimum?","options":["Q = 10; ATC = ₹30","Q = 5; ATC = ₹35","Q = 10; ATC = ₹20","Q = 20; ATC = ₹35"],"answer":0,"explanation":"ATC = 100/Q + 10 + Q is lowest where MC = ATC: 10 + 2Q = 100/Q + 10 + Q gives Q = 10, and ATC = 10 + 10 + 10 = ₹30. ₹20 forgets the fixed cost per unit.","difficulty":"very-hard","source":"RBI Grade B Phase 2"},
  {"id":"eco-basics-209","question":"A competitive firm with total cost TC = 100 + 10Q + Q² can sell any quantity at ₹50. Its profit-maximising output and profit are:","options":["Q = 25; profit ₹275","Q = 20; profit ₹300","Q = 20; profit ₹400","Q = 40; loss of ₹100"],"answer":1,"explanation":"Set P = MC: 50 = 10 + 2Q, so Q = 20. Profit = 50 × 20 − (100 + 200 + 400) = ₹300. ₹400 forgets the fixed cost of ₹100.","difficulty":"hard","source":"RBI Grade B Phase 2 · SSC CGL Tier 2"},
  {"id":"eco-basics-210","question":"A shop owner reports an accounting profit of ₹5 lakh. To run the shop she gave up a salaried job paying ₹6 lakh, and her own capital in the shop could have earned ₹1 lakh elsewhere. Her economic profit is:","options":["₹5 lakh","−₹1 lakh","−₹2 lakh","₹12 lakh"],"answer":2,"explanation":"Economic profit = accounting profit − implicit costs = 5 − 6 − 1 = −₹2 lakh. Counting only the forgone salary gives −₹1 lakh; economically she would be better off in the job.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-basics-211","question":"A firm has fixed costs of ₹10,000, sells its product at ₹50 and has an average variable cost of ₹30. Its break-even output is:","options":["200 units","333 units","250 units","500 units"],"answer":3,"explanation":"Each unit contributes 50 − 30 = ₹20 towards fixed costs, so break-even output = 10,000/20 = 500 units. Dividing by the price (200) ignores variable costs.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-basics-212","question":"For the last unit bought, good X (price ₹10) gives a marginal utility of 40 and good Y (price ₹20) gives 60. With the same budget, to raise her total utility the consumer should:","options":["Buy more Y and less X, since Y gives more satisfaction per unit","Keep the same bundle, since both goods give positive marginal utility","Buy less X and more Y, since Y has the higher marginal utility","Buy more X and less Y, since X gives more utility per rupee"],"answer":3,"explanation":"MU per rupee is 40/10 = 4 for X and 60/20 = 3 for Y. Shifting spending towards X raises utility until MUx/Px = MUy/Py (the equi-marginal principle).","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-basics-213","question":"Assertion (A): Every Giffen good is an inferior good, but not every inferior good is a Giffen good. Reason (R): For a Giffen good, the negative income effect of a price change is strong enough to outweigh the substitution effect.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"For most inferior goods the substitution effect dominates and demand still falls when price rises. Only when the perverse income effect is large enough does demand rise with price, making the good a Giffen good.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-basics-214","question":"Under the RBI's framework for early recognition of stress, a term loan whose instalment has been overdue for 75 days is classified as:","options":["SMA-1","SMA-2","Sub-standard asset (NPA)","SMA-0"],"answer":1,"explanation":"Special Mention Accounts are SMA-0 (up to 30 days overdue), SMA-1 (31–60 days) and SMA-2 (61–90 days). An account becomes an NPA only when overdue for more than 90 days.","difficulty":"very-hard","source":"RBI Grade B · IBPS PO Mains"},
  {"id":"eco-basics-215","question":"Under the Insolvency and Bankruptcy Code, 2016, as amended in 2019, the corporate insolvency resolution process must ordinarily be completed within:","options":["90 days, extendable by 90 days, with an outer limit of 270 days","270 days, with no extension allowed under any circumstances","180 days, extendable by 90 days, with an outer limit of 330 days","365 days, extendable by 180 days, with an outer limit of 545 days"],"answer":2,"explanation":"The Code allows 180 days plus a one-time extension of up to 90 days; the 2019 amendment set an outer limit of 330 days including time spent in litigation.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims"},
  {"id":"eco-basics-216","question":"Domestic scheduled commercial banks must lend at least what share of their adjusted net bank credit (or credit equivalent of off-balance-sheet exposure, whichever is higher) to the priority sector?","options":["40%","18%","32%","50%"],"answer":0,"explanation":"The overall priority sector target for domestic banks is 40%. 18% is the sub-target for agriculture, a common trap.","difficulty":"hard","source":"RBI Grade B · IBPS PO Mains"},
  {"id":"eco-basics-217","question":"Since 2018–19, the Government has fixed Minimum Support Prices for notified kharif crops at no less than:","options":["1.5 times the C2 cost","1.5 times the A2+FL cost","1.25 times the A2+FL cost","2 times the A2 cost"],"answer":1,"explanation":"The 2018–19 Budget committed to MSP of at least one and a half times the cost of production, which CACP measures as A2+FL (paid-out costs plus imputed family labour). The Swaminathan Commission had sought 1.5 times the fuller C2 cost.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"eco-basics-218","question":"How many of these statements about the National Food Security Act, 2013 are correct? I. It covers up to 75% of the rural and 50% of the urban population. II. Priority households are entitled to 5 kg of foodgrains per person per month. III. Antyodaya Anna Yojana households are entitled to 35 kg per household per month. IV. Entitlements are given only to families below the Tendulkar poverty line.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Beneficiaries are identified by States within the coverage ceilings, which are far wider than the Tendulkar poverty line, so IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"eco-basics-219","question":"Match the WTO domestic support category with its description: 1. Amber box 2. Blue box 3. Green box; a. Support with minimal trade distortion, such as research and extension b. Trade-distorting support that is subject to reduction commitments c. Direct payments under programmes that limit production","options":["1-a, 2-c, 3-b","1-c, 2-b, 3-a","1-b, 2-a, 3-c","1-b, 2-c, 3-a"],"answer":3,"explanation":"Amber box support such as price support distorts trade and must be capped; blue box payments are tied to production-limiting schemes; green box measures are exempt as they cause little distortion.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"eco-basics-220","question":"Match the trade remedy with the situation it addresses: 1. Anti-dumping duty 2. Countervailing duty 3. Safeguard duty; a. A sudden surge of imports seriously injuring domestic industry, even if trade is fair b. Imports priced below their normal value in the exporter's home market c. Imports that benefit from subsidies in the exporting country","options":["1-b, 2-c, 3-a","1-c, 2-b, 3-a","1-a, 2-c, 3-b","1-b, 2-a, 3-c"],"answer":0,"explanation":"Anti-dumping duty offsets unfairly low pricing, countervailing duty offsets foreign subsidies, and a safeguard duty gives temporary relief from an import surge without any finding of unfair trade.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-basics-221","question":"Under free trade a final good sells for ₹100 and uses imported inputs worth ₹60. India now levies a 20% tariff on the final good and a 10% tariff on the input. The effective rate of protection for the domestic producer is:","options":["20%","54%","35%","10%"],"answer":2,"explanation":"Value added rises from 100 − 60 = ₹40 to 120 − 66 = ₹54, so effective protection = 14/40 = 35%. It exceeds the 20% nominal tariff because inputs are taxed less than the output.","difficulty":"very-hard","source":"RBI Grade B Phase 2"},
  {"id":"eco-basics-222","question":"The 'infant industry' argument in trade policy is used to justify:","options":["Permanent tariffs on all manufactured imports to save foreign exchange","Temporary protection for a new industry until it gains scale and skills","Export subsidies for industries that are already mature and competitive","A ban on foreign investment in all industries of strategic importance"],"answer":1,"explanation":"A young industry may have high costs at first; temporary protection lets it learn and grow to an efficient size, after which protection should be withdrawn.","difficulty":"moderate","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-basics-223","question":"When the price of tea rises by 10%, the quantity of coffee demanded rises by 5%. The cross-price elasticity and the relationship between the goods are:","options":["−0.5; complements","+2.0; substitutes","−2.0; complements","+0.5; substitutes"],"answer":3,"explanation":"Cross elasticity = % change in coffee demand ÷ % change in tea price = 5/10 = +0.5. A positive value means the goods are substitutes; 2.0 inverts the ratio.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"eco-basics-224","question":"Match the institution with its headquarters: 1. Asian Infrastructure Investment Bank 2. New Development Bank 3. Asian Development Bank 4. International Monetary Fund; a. Washington, D.C. b. Manila c. Shanghai d. Beijing","options":["1-c, 2-d, 3-b, 4-a","1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-b, 4-a","1-d, 2-c, 3-a, 4-b"],"answer":2,"explanation":"The AIIB is in Beijing, the BRICS-led New Development Bank in Shanghai, the ADB in Manila and the IMF in Washington, D.C.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-basics-225","question":"Match the committee with its subject: 1. Narasimham Committee (1991) 2. Tarapore Committee (1997) 3. Nachiket Mor Committee (2013) 4. Kelkar Task Forces (2002); a. Direct and indirect tax reform b. Capital account convertibility c. Comprehensive financial services for small businesses and low-income households d. Reform of the financial system","options":["1-b, 2-d, 3-c, 4-a","1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-b, 4-a","1-a, 2-b, 3-c, 4-d"],"answer":1,"explanation":"Narasimham (1991) recommended financial sector reforms, Tarapore a road map to capital account convertibility, Nachiket Mor financial inclusion, and the Kelkar task forces reform of direct and indirect taxes.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-basics-226","question":"Say's law, which Keynes rejected, states that:","options":["Supply creates its own demand, so general overproduction cannot last","Demand creates its own supply, so output always follows spending","Saving and investment are equalised only by changes in income","Wages are rigid downwards, so unemployment can persist for long"],"answer":0,"explanation":"Say argued that producing goods generates the income to buy them, so a general glut is impossible. Keynes showed that saving can leak out of spending and leave demand short, so unemployment can persist.","difficulty":"moderate","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-basics-227","question":"In Keynes's General Theory, the level of employment in the short run is determined by:","options":["The real wage fixed in a competitive labour market","The quantity of money circulating in the economy","The interest rate set by the supply of savings","Effective demand for goods and services"],"answer":3,"explanation":"Keynes argued that firms hire as many workers as needed to meet effective demand, the point where aggregate demand equals aggregate supply, which can be below full employment.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-basics-228","question":"National income is ₹1,000 crore. Undistributed corporate profits are ₹50 crore, corporation tax ₹40 crore, transfer payments to households ₹60 crore and personal direct taxes ₹70 crore. Ignoring other items, personal disposable income is:","options":["₹900 crore","₹970 crore","₹1,040 crore","₹840 crore"],"answer":0,"explanation":"Personal income = 1,000 − 50 − 40 + 60 = ₹970 crore; personal disposable income = 970 − 70 = ₹900 crore. ₹970 crore forgets personal taxes, and ₹840 crore leaves out the transfer payments.","difficulty":"very-hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"eco-basics-229","question":"Full-employment income is ₹1,200 crore, but equilibrium income is only ₹1,000 crore. The marginal propensity to consume is 0.75. The deflationary gap is:","options":["₹200 crore","₹50 crore","₹800 crore","₹150 crore"],"answer":1,"explanation":"The deflationary gap is the shortfall of aggregate demand at full employment. With a multiplier of 1/(1 − 0.75) = 4, an income shortfall of ₹200 crore needs only 200/4 = ₹50 crore of extra demand.","difficulty":"very-hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-basics-230","question":"Water is essential to life yet cheap, while diamonds are inessential yet very dear. The marginalist resolution of this 'paradox of value' is that:","options":["Price reflects total utility, which is higher for diamonds than for water","Price reflects only the labour used, which is far greater for diamonds","Water is a public good, so the market cannot put a price on it","Price reflects marginal utility, which is low for abundant water"],"answer":3,"explanation":"Total utility of water is huge, but because it is plentiful the last unit adds little satisfaction; scarce diamonds have high marginal utility. Prices follow marginal, not total, utility.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-basics-231","question":"Assertion (A): A competitive firm earning zero economic profit in the long run is still covering its owner's opportunity costs. Reason (R): Normal profit is included in the firm's average cost curve.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Economic costs include the normal return the owner could earn elsewhere; when price equals average cost, that normal profit is earned, so zero economic profit is not a loss.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-basics-232","question":"Which of these is an EXTERNAL economy of scale?","options":["Bulk-buying discounts on raw materials for a large firm","Use of large specialised machines inside one big plant","Hiring specialist managers once a firm grows large enough","A pool of skilled labour and suppliers in an industrial cluster"],"answer":3,"explanation":"External economies arise from the growth of the whole industry or region and lower costs for every firm in it, as in clusters like Tiruppur or Bengaluru. The others are internal economies of a single firm's size.","difficulty":"very-hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-basics-233","question":"A monopolist sells the same product in two separated markets. At its profit-maximising prices, the price elasticity of demand is 2 in market 1 and 4 in market 2 (absolute values). The ratio of the price in market 1 to the price in market 2 is:","options":["1.5","2.0","0.67","1.0"],"answer":0,"explanation":"Profit maximisation requires equal MR in both markets: P1(1 − 1/2) = P2(1 − 1/4), so P1/P2 = 0.75/0.5 = 1.5. The less elastic market pays more; the ratio is not simply 4/2.","difficulty":"very-hard","source":"RBI Grade B Phase 2"},
  {"id":"eco-basics-234","question":"A 'natural monopoly' arises when:","options":["A government grants one firm a patent on a new product","Average cost keeps falling over the whole range of market demand","A single firm owns the entire supply of a key natural resource","Rival firms agree to divide the market and fix a common price"],"answer":1,"explanation":"With huge fixed costs, as in power transmission or water pipelines, one firm can serve the whole market more cheaply than two. Patents and resource ownership are legal or resource barriers, and collusion is a cartel.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
  {"id":"eco-basics-235","question":"A software engineer earns ₹50,000 a month; the best alternative job open to her pays ₹35,000. Her economic rent and transfer earnings are:","options":["₹35,000 and ₹15,000","₹50,000 and ₹35,000","₹15,000 and ₹50,000","₹15,000 and ₹35,000"],"answer":3,"explanation":"Transfer earnings are what she would get in her next best use (₹35,000); economic rent is the surplus above that, 50,000 − 35,000 = ₹15,000.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-basics-236","question":"Alfred Marshall's concept of 'quasi-rent' refers to:","options":["Rent paid to landlords for land of above-average fertility","The long-run surplus earned by any factor in fixed supply","Short-run earnings of fixed factors above variable costs","The excess of a worker's wage over the legal minimum wage"],"answer":2,"explanation":"In the short run machines and plant cannot be changed, so whatever revenue exceeds variable cost is a rent-like return to them; it disappears in the long run as capacity adjusts.","difficulty":"very-hard","source":"RBI Grade B Phase 2"},
  {"id":"eco-basics-237","question":"In a competitive market a firm's 5th worker would add 8 units of output a day. The product sells for ₹50 a unit and the daily wage is ₹450. The firm should:","options":["Hire the worker, as the output of 8 units is positive","Hire the worker, as the wage is below the average product's value","Hire the worker, as total revenue still rises with more output","Not hire the worker, as MRP of ₹400 is below the ₹450 wage"],"answer":3,"explanation":"Marginal revenue product = 8 × 50 = ₹400, which is less than the ₹450 wage, so hiring would cut profit. A firm hires until MRP equals the wage.","difficulty":"very-hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-basics-238","question":"How many of these statements about the Green Revolution in India are correct? I. It was centred at first on high-yielding varieties of wheat. II. Its early gains were concentrated in Punjab, Haryana and western Uttar Pradesh. III. It relied on assured irrigation, chemical fertilisers and HYV seeds. IV. Its largest early gains were in pulses and coarse grains.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Pulses and coarse grains gained little; the package favoured wheat and later rice in irrigated areas, so IV is wrong.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"eco-basics-239","question":"Operation Flood, launched in 1970, which made India a leading milk producer, was led by:","options":["M. S. Swaminathan, through the ICAR","Verghese Kurien, through the NDDB","Norman Borlaug, through CIMMYT","C. Subramaniam, through the FCI"],"answer":1,"explanation":"Verghese Kurien led Operation Flood through the National Dairy Development Board, spreading the Anand pattern of dairy cooperatives. Swaminathan, Borlaug and Subramaniam are linked with the Green Revolution.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-basics-240","question":"Match the form of economic integration with its feature: 1. Free trade area 2. Customs union 3. Common market 4. Economic union; a. Free trade plus a common external tariff b. Members remove tariffs among themselves but keep their own external tariffs c. A common market plus harmonised economic policies, often with a common currency d. A customs union plus free movement of labour and capital","options":["1-a, 2-b, 3-d, 4-c","1-b, 2-a, 3-c, 4-d","1-b, 2-d, 3-a, 4-c","1-b, 2-a, 3-d, 4-c"],"answer":3,"explanation":"Each stage adds to the previous one: an FTA removes internal tariffs, a customs union adds a common external tariff, a common market adds factor mobility, and an economic union adds common policies.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"eco-basics-241","question":"The WTO's 'most-favoured-nation' principle requires a member to:","options":["Extend to all members any trade advantage it gives to one member","Treat imported goods like domestic goods once they enter its market","Give developing countries lower tariffs than developed countries","Remove all of its tariffs within an agreed number of years"],"answer":0,"explanation":"MFN means non-discrimination between trading partners: a concession to one must go to all, with exceptions such as free trade areas. Treating imports like domestic goods is the separate 'national treatment' principle.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"eco-basics-242","question":"In the second stage of the demographic transition:","options":["Birth and death rates are both high, so population grows slowly","Death rates fall sharply but birth rates stay high, so population grows fast","Birth rates fall towards death rates, so population growth slows down","Birth and death rates are both low, so population is nearly stable"],"answer":1,"explanation":"Better health and food cut death rates first, while birth rates fall only later with social change; the gap causes a population explosion. The other options describe stages one, three and four.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"eco-basics-243","question":"The Eleventh Five-Year Plan (2007–12) had as its theme:","options":["Faster, more inclusive and sustainable growth","Towards faster and more inclusive growth","Growth with social justice and equality","Removal of poverty and attainment of self-reliance"],"answer":1,"explanation":"The Eleventh Plan aimed at 'faster and more inclusive growth'; the Twelfth (2012–17) added 'sustainable'. Growth with social justice was the Ninth Plan's focus and removal of poverty the Fifth's.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"eco-basics-244","question":"How many of these statements about a firm's short-run cost curves are correct? I. When marginal cost is below average cost, average cost is falling. II. The marginal cost curve cuts both the AVC and ATC curves at their minimum points. III. Average fixed cost falls continuously as output rises. IV. The vertical gap between ATC and AVC widens as output rises.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. The gap between ATC and AVC is average fixed cost, which keeps falling, so the two curves get closer as output rises; IV is wrong.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-basics-245","question":"The Fifth Five-Year Plan (1974–79), which aimed at the removal of poverty and self-reliance, was:","options":["Completed in full and followed by a three-year 'Plan holiday'","Replaced midway by an action agenda prepared by NITI Aayog","Abandoned in its first year because of a war with Pakistan","Ended a year early, in 1978, by the Janata Government"],"answer":3,"explanation":"The Janata Government ended the Fifth Plan in 1978 and started a rolling plan for 1978–80. The Plan holiday (1966–69) followed the Third Plan, and NITI Aayog came only in 2015.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"eco-basics-246","question":"How many of these statements are correct? I. The Planning Commission was set up in March 1950 by a resolution of the Union Cabinet. II. The Planning Commission was a constitutional body. III. The National Development Council was set up in 1952. IV. The Prime Minister was the ex officio chairman of the Planning Commission.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, III and IV are correct. The Planning Commission was created by executive resolution and had no constitutional or statutory basis, so II is wrong.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"eco-basics-247","question":"Which of these is a STOCK variable rather than a flow?","options":["The fiscal deficit","Exports of goods","Foreign exchange reserves","Gross investment"],"answer":2,"explanation":"A stock is measured at a point in time, like reserves held on 31 March; flows are measured over a period, like a year's deficit, exports or investment. Deficits add to the stock of debt.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"eco-basics-248","question":"In the four-sector model of the circular flow of income, which group consists only of leakages (withdrawals)?","options":["Saving, taxes and imports","Investment, government spending and exports","Saving, investment and exports","Taxes, transfer payments and imports"],"answer":0,"explanation":"Saving, taxes and imports take money out of the income–spending loop; investment, government spending and exports inject it. Transfer payments add to household income, so they are not withdrawals.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-basics-249","question":"Assertion (A): In a two-sector economy, realised (ex post) saving always equals realised investment. Reason (R): Unplanned changes in inventories make up any gap between planned saving and planned investment.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"If households plan to save more than firms plan to invest, unsold goods pile up as unplanned inventory investment, so measured saving and investment are equal; the mismatch then drives income towards equilibrium.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"eco-basics-250","question":"Economies of scope exist when:","options":["Average cost falls as the output of a single product rises","Producing two products together costs less than producing them apart","Firms in a cluster gain from shared suppliers and skilled labour","Average cost rises as a firm grows too large to manage well"],"answer":1,"explanation":"Economies of scope come from sharing inputs across products, such as a bank selling loans and insurance through the same branches. The first option is economies of scale and the last diseconomies of scale.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2"},
];

export default questions;
